	replaceDoubleLineBreaks() {
		if (this.bodyControl) {
			if (!this.isHtml) {
				const r1 = this.bodyControl.value.replaceAll('\r\n\r\n', '\r\n');
				const r2 = r1.replaceAll('\n\n', '\n');
				if (r2 === this.bodyControl.value) {
					this.alertService.warn($localize`Nothing altered`);
				} else {
					this.bodyControl.setValue(r2);
					this.bodyControl.markAsDirty();
				}
			} else {
				const b1 = this.bodyControl.value.replaceAll('<br><br>', '<br>').replaceAll('<div><br></div><div><br></div>', '<div><br></div>');
				if (b1 === this.bodyControl.value) {
					this.alertService.warn($localize`Nothing altered`);
				} else {
					this.bodyControl.setValue(b1);
					this.bodyControl.markAsDirty();
				}
			}
		}
	}

