	/**
	 * paste as plain text preserving link breaks as br.
	 */
	pastFromClipboardAsPlainText() {
		if (this.htmlEditor) {
			navigator.clipboard.readText().then( //on Firefox, need to follow https://stackoverflow.com/questions/67440036/navigator-clipboard-readtext-is-not-working-in-firefox first.
				s => {
					//s is already plaintext with line breaks
					const htmlText = HtmlFunc.textToHtmlTextWithBr(s);
					if (htmlText) {
						this.htmlEditor!.focus(); //need to focus first, otherwise, the paste will go to last focused input.
						this.htmlEditorService.insertHtml(htmlText);
					}
				}
			);
		}
	}

