import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, Component, EventEmitter, Input, Output } from '@angular/core';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { AngularEditorModule } from '@kolkov/angular-editor';
import { AlertService, WaitService } from 'nmce';
import { NmceHtmlEditorModule } from 'nmce-html-editor';
import { Fonlow_PoemsApp_Data_Client, PoemsApp_Controllers_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { EditPoemSubjectService } from '../_services/types';
import { NGMDModule } from '../ngmd.module';


@Component({
    selector: 'not-local-image',
    templateUrl: 'not-local-image.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [		CommonModule, FormsModule, ReactiveFormsModule,  NGMDModule, AngularEditorModule,
		NmceHtmlEditorModule,
		]
})
export class NotLocalImageComponent {
	@Input()
	srcUrl?: string;

	@Input()
	poemIds: string[] = [];

	@Input()
	poemBriefsDic?: { [id: string]: Fonlow_PoemsApp_Data_Client.PoemBrief };

	//name?: string;
	description?: string;

	@Output()
	imageHandled: EventEmitter<string> = new EventEmitter<string>();

	constructor(
		private picturesService: PoemsApp_Controllers_Client.Files,
		private alertService: AlertService,
		private editPoemSubjectService: EditPoemSubjectService,
		private waitService: WaitService,
	) {
	}

	editPoem(poemId: string) {
		this.editPoemSubjectService.emit(poemId);
	}

	makeLocalImage(srcUrl: string) {
		this.waitService.setWait({ loading: true });
		this.picturesService.downloadRemoteToLocal({
			poemIds: this.poemIds,
			srcUrl: srcUrl,
			description: this.description,
			//name: this.name
		}).subscribe({
			next: pm => {
				this.waitService.setWait({ loading: false });
				this.alertService.success('Done');
				this.imageHandled.emit(srcUrl);
			},
			error: error => {
				this.alertService.error(error);
				this.waitService.setWait({ loading: false });
			}
		})
	}
}

