import { Component, Inject, Injectable, OnDestroy, OnInit } from '@angular/core';
import { FormGroup, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { Observable, Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';

import { MAT_DIALOG_DATA, MatDialog } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { AlertService, ConfirmService, NmceComponentsModule, PasswordsInputService, WaitService } from 'nmce';
import { Fonlow_AspNetCore_Identity_Client, Fonlow_Auth_Controllers_Client,  } from '../../clientapi/WebApiNG2ClientAuto';
import { CommonModule } from '@angular/common';
import { NGMDModule } from '../ngmd.module';
import { RolesComponent } from './roles.component';

/**
 * Display and edit an existing user.
 */
@Component({
    templateUrl: 'user.component.html',
    standalone: true,
	imports: [
		CommonModule,
		FormsModule,
		ReactiveFormsModule,
		NGMDModule,	

		RolesComponent,
	],
})
export class UserComponent implements OnInit, OnDestroy {
	model?: Fonlow_AspNetCore_Identity_Client.UserInfoViewModel;
	modelForm: FormGroup<Fonlow_AspNetCore_Identity_Client.UserInfoViewModelFormProperties>;
	loading = false;
	//avatarImage: Observable<Response> = new Observable<Response>();


	private unsubscribe: Subject<void> = new Subject();

	constructor(
		@Inject(MAT_DIALOG_DATA) public userId: string,
		private service: Fonlow_Auth_Controllers_Client.Account,
		private alertService: AlertService,
		private waitService: WaitService,
		private router: Router,
		private confirmService: ConfirmService,
		private passwordsInputService: PasswordsInputService,
	) {
		console.debug('UserComponent created');
		this.modelForm = Fonlow_AspNetCore_Identity_Client.CreateUserInfoViewModelFormGroup();
	}

	ngOnInit(): void {
		this.service.getUserInfoByIdOfstring(this.userId).subscribe(
			{
				next: data => {
					this.model = data;
					this.modelForm.patchValue(this.model);
				},
				error: error => this.alertService.error(error)
			}
		);
	}

	ngOnDestroy(): void {
		this.unsubscribe.next();
		this.unsubscribe.complete();
	}

	save() {
		if (this.model) {
			this.loading = true;
			this.waitService.setWait({ loading: true });
			const raw = this.modelForm.getRawValue();
			Object.assign(this.model, raw);
			const userUpdate: Fonlow_AspNetCore_Identity_Client.UserUpdate = {
				id: this.model.id,
				fullName: this.model.fullName,
				email: this.model.email,
			};

			this.service.update(userUpdate).pipe(takeUntil(this.unsubscribe)).subscribe(
				{
					next: () => {
						this.modelForm.markAsPristine();
						this.alertService.success($localize`Update successful for ${this.model!.userName}`, true);
						this.waitService.setWait({ loading: false });
						this.loading = false;
					},
					error: error => {
						this.alertService.error(error);
						this.loading = false;
						this.waitService.setWait({ loading: false });
					}
				});
		} else {
			this.alertService.warn($localize`Nothing to save.`);
		}
	}

	delete() {
		if (this.userId) {
			this.confirmService.openDefault().pipe(takeUntil(this.unsubscribe)).subscribe(
				r => {
					if (r) {
						this.service.removeUser(this.userId).subscribe(() => {
							this.alertService.success($localize`user ${this.model!.userName} deleted.`);
							this.router.navigate(['/account/users']);
						});
					}
				});
		} else {
			this.alertService.warn($localize`Nothing to deelte.`);
		}
	}

	changePassword() {
		this.passwordsInputService.open($localize`Set New Password`).pipe(takeUntil(this.unsubscribe)).subscribe(
			{
				next: data => {
					if (data) {
						this.service.setUserPassword({ userId: this.model!.id, newPassword: data, confirmPassword: data }).pipe(takeUntil(this.unsubscribe)).subscribe(() => {
							this.alertService.info($localize`Updated`, true);
						},
							error => {
								console.error(error);
								this.alertService.error(error);
							});
					}
				},
				error: error => {
					console.error(error);
					this.alertService.error(error);
				}
			}
		);



	}
}


@Injectable()
export class UserDialogService {
	constructor(private dialog: MatDialog) { }

	/**
	 * Display poem object in editor.
	 * @param data
	 */
	open(userId: string): Observable<void> {
		const modalRef = this.dialog.open(UserComponent, {
			disableClose: true,
			autoFocus: false,
			minWidth: '98vw',
			minHeight: '98vh',
			panelClass: 'dialog-full-content-height',
			data: userId
		});

		return modalRef.afterClosed();
	}

}
