	private renderRyhmesSelect() {
		if (this.poem.ryhmesCsv && !this.ryhmesSelectRendered) {
			const ryhmesArray = this.poem.ryhmesCsv.split(',');
			for (const c of this.ryhmesSelect!.options) {
				if (ryhmesArray.findIndex(d => d === c.value.code) >= 0) {
					c.select();
				}
			}

			this.ryhmesSelectRendered=true;
		}
	}

	/**
	 * Called by the Save button.
	 */
	save() {
		if (!this.noteControl.value) {
			this.alertService.warn($localize`Not allow to save empty document.`); //however, if the title is empty, the backend will use the first line as title.
			return;
		}

		this.saveAndOptionallyClose(true);
	}

	private extractTitleFromBody(b: string | null | undefined) {
		if (b) {
			let idx = b.indexOf('\r\n');
			if (idx < 0) {
				idx = b.indexOf('\n');
			}

			if (idx >= 0) { //title max length is 128
				return b.substring(0, idx > 127 ? 127 : idx);
			}

			return b.substring(0, b.length < 128 ? b.length - 1 : 127);
		} else {
			return ''
		}
	}

	/**
	 * Save through add or update DB and optionally close. And do postUpdateHandling().
	 * @param toClose true to close
	 */
	private saveAndOptionallyClose(toClose: boolean) {
		const raw = this.getRawFromPoemForm();
		if (this.poem.id) {
			this.poemsService.update(raw).subscribe(
				{
					next: () => {
						this.postUpdateHandling(raw);
						if (toClose) {
							this.dialogRef.close();
						}
					},
					error: error => this.alertService.error(error)
				}
			);
		} else {
			this.poemsService.add(raw).subscribe(
				{
					next: newPoem => {
						this.postAddHandling(newPoem);
						if (toClose) {
							this.dialogRef.close();
						}
					},
					error: error => this.alertService.error(error)
				}
			);
		}
	}

	/**
	 * handle local issues after adding poem to DB. And tell the other local parts a poem is added. detectChanges()
	 * @param newPoem
	 */
	private postAddHandling(newPoem: Fonlow_PoemsApp_Data_Client.Poem) {
		this.poem = newPoem;
		this.poemForm.reset(undefined);
		this.poemForm.patchValue(this.poem);
		this.poemForm.markAsPristine();
		this.ref.detectChanges();
		this.alertService.success($localize`Added`, true);
		this.newPoemAddedSubjectService.emit(this.poem); //main will insert new brief
	}

	/**
	 * Tell the other local parts a poem is updated. this.poem is kept the same with relationships with tags and annotations etc.
	 * @param raw
	 */
	private postUpdateHandling(raw: any) {
		this.poemForm.markAsPristine();
		this.ref.detectChanges();
		this.alertService.success($localize`Updated`, true);
		this.poemModifiedSubjectService.emit(raw); // main will update existing brief found in briefs; and viewer will update data
	}

	private getRawFromPoemForm() {
		let plainText: string | null | undefined;
		if (!this.poemForm.controls.title.value) {
			if (this.poemForm.controls.bodyType.value === Fonlow_PoemsApp_Data_Client.BodyType.Text) {
				const title = this.extractTitleFromBody(this.poemForm.controls.body.value);
				this.poemForm.controls.title.setValue(title);
			} else if (this.poemForm.controls.bodyType.value === Fonlow_PoemsApp_Data_Client.BodyType.HTML) {
				plainText = HtmlFunc.getHtmlPlainText(this.poemForm.controls.body.value, true);
				const title = this.extractTitleFromBody(plainText);
				this.poemForm.controls.title.setValue(title);
			}
		}

		const raw: any = this.poemForm.getRawValue();
		if (this.poemForm.controls.bodyType.value === Fonlow_PoemsApp_Data_Client.BodyType.HTML) {
			if (!plainText) {
				plainText = HtmlFunc.getHtmlPlainText(this.poemForm.controls.body.value, true);
			}

			raw.bodyPlain = plainText;
		}

		raw.albumIds = this.poem.albumIds;
		raw.tagIds = this.poem.tagIds;
		raw.annotationIds = this.poem.annotationIds;
		raw.numberedAnnotationBriefs = this.poem.numberedAnnotationBriefs;
		JsonFunc.removeNullFields(raw);
		return raw;
	}

	/**
	 * Reset poem and poemForm, new or existing one.
	 */
	reset() {
		if (this.poem.id) {
			this.poemsService.get(this.poem.id, APP_DI_CONFIG.convertZhHandler).subscribe(
				{
					next: r => {
						if (r) {
							this.poem = r;
							this.poemForm.reset(undefined);
							this.poemForm.patchValue(r);
							this.ref.detectChanges();
						} else {
							this.alertService.warn($localize`Not found`);
						}
					},
					error: error => this.alertService.error(error)
				}
			)
		} else {
			this.poem = {
				bodyType: Fonlow_PoemsApp_Data_Client.BodyType.HTML,
				tagIds: [], albumIds: [], annotationIds: []
			};
			this.poemForm.reset(undefined);
			this.poemForm.patchValue(this.poem);
		}
	}

	/**
	 * Close after checking if poemForm is dirty.
	 */
	close() {
		if (this.poemForm.dirty) {
			this.confirmService.open($localize`Quit Editing`, $localize`The record is altered. Are you sure to quit without saving?`, $localize`Quit`, $localize`Stay`).subscribe(
				r => {
					if (r) {
						this.dialogRef.close();
					}
				}
			);
		} else {
			this.poemModifiedSubjectService.emit(null);
			this.dialogRef.close();
		}
	}

