	// #region Albums

	private refreshAlbumCandidates() {
		this.albumCandidates = AppCache.albums.slice(); //clone array
		for (let i = this.albumCandidates.length - 1; i >= 0; i--) {
			const t = this.albumCandidates[i];
			const existsInPoemAlbums = this.poem.albumIds!.findIndex(k => k === t.id) >= 0;
			if (existsInPoemAlbums) {
				console.debug(this.albumCandidates[i].title + 'to be removed from candidates.');
				this.albumCandidates.splice(i, 1);
			}
		}
	}

	private filterAlbumList(val: string): Array<Fonlow_PoemsApp_Data_Client.Album> {
		return this.albumCandidates.filter(option =>
			option.title!.toUpperCase().indexOf(val.toUpperCase()) >= 0)
			.slice(0, this.maxDropDownItem);
	}

	removeAlbum(albumId: string) {
		if (this.poem.id) {
			this.poemsService.dissociateAlbum(this.poem.id, albumId).subscribe(
				{
					next: () => {
						const index = this.poem.albumIds?.indexOf(albumId)!;
						if (index >= 0) {
							this.poem.albumIds?.splice(index, 1);
							this.refreshAlbumCandidates();
							this.ref.detectChanges();
							this.newAlbumAddedSubjectService.emit({ poem: this.poem });
						}
					},
					error: error => this.alertService.error(error)
				}
			)
		} else {

		}
	}

	albumSelected(event: MatAutocompleteSelectedEvent) {
		this.newAlbumControl.setValue(undefined);
		this.albumChipInput!.nativeElement.value = ''; //need to this according to ng md demo, probably because the formControl is not contained in FormGroup, or coupling with the other components.

		const value = (event.option.viewValue || '').trim();
		if (value) {
			if (this.poem.id) {
				this.associateExistingAlbumWithPoem(value);
			} else {
				const raw = this.getRawFromPoemForm();
				this.poemsService.add(raw).subscribe(
					{
						next: newPoem => {
							this.postAddHandling(newPoem); //detect changes inside
							this.associateExistingAlbumWithPoem(value);
						},
						error: error => this.alertService.error(error)
					}
				);

			}
		}
	}

	private associateExistingAlbumWithPoem(albumTitle: string) {
		const existingAlbum = AppCache.albums.find(d => d.title === albumTitle);
		const albumed = this.poem.albumIds!.indexOf(existingAlbum?.id!) >= 0;
		if (albumed) {
			this.alertService.warn($localize`${albumTitle} already includes ${this.poem.title}.`, true);
			return;
		}

		if (this.poem.id) {
			if (existingAlbum) {
				this.poemsService.associateAlbumWithPoems(existingAlbum.id!, [this.poem.id!]).subscribe(
					{
						next: () => {
							this.poem.albumIds?.push(existingAlbum.id!);
							this.refreshAlbumCandidates();
							this.ref.detectChanges();
							this.newAlbumAddedSubjectService.emit({ poem: this.poem });
						},
						error: error => this.alertService.error(error)
					}
				)
			} else {
				this.alertService.error($localize`No supporting new album here.`);
			};
		} else {
			const raw = this.getRawFromPoemForm();
			this.poemsService.add(raw).subscribe(
				{
					next: newPoem => {
						this.postAddHandling(newPoem);
						this.associateExistingAlbumWithPoem(albumTitle);
					},
					error: error => this.alertService.error(error)
				}
			);
		}
	}

	addAlbum(event: MatChipInputEvent): void {
		const value = (event.value || '').trim();
		this.newAlbumControl.setValue(undefined);
		event.chipInput!.clear();
		if (value) {
			if (this.poem.id) {
				this.associateNewAlbumWithPoem(value);
			} else {
				const raw = this.getRawFromPoemForm();
				this.poemsService.add(raw).subscribe(
					{
						next: newPoem => {
							this.postAddHandling(newPoem);
							this.associateNewAlbumWithPoem(value);
						},
						error: error => this.alertService.error(error)
					}
				);
			}
		}
	}

	private associateNewAlbumWithPoem(value: string) {
		const existingAlbum = AppCache.albums.find(d => d.title === value);
		const tagged = this.poem.albumIds!.indexOf(existingAlbum?.id!) >= 0;
		if (tagged) {
			this.alertService.warn($localize`${value} already in albums`, true);
			return;
		}

		if (existingAlbum) {
			this.poemsService.associateAlbumWithPoems(existingAlbum.id!, [this.poem.id!]).subscribe(
				{
					next: () => {
						this.poem.albumIds?.push(existingAlbum.id!);
						this.ref.detectChanges();
						this.newAlbumAddedSubjectService.emit({ poem: this.poem });
					},
					error: error => this.alertService.error(error)
				}
			)
		} else {
			this.alertService.warn($localize`You can select from only existing albums.`);
		};
	}

