	/**
	 * 
	 * @param tagName may be existing or new
	 */
	private associateTagNameWithPoem(tagName: string) {
		const existingTag = AppCache.tags.find(d => d.name === tagName);
		const tagged = this.poem.tagIds!.indexOf(existingTag?.id!) >= 0;
		if (tagged) {
			this.alertService.warn($localize`Already tagged with ${tagName}`, true);
			return;
		}

		if (existingTag) {
			this.poemsService.associateWithExistingTags(this.poem.id!, [existingTag.id!]).subscribe(
				{
					next: () => {
						this.poem.tagIds?.push(existingTag.id!);
						this.ref.detectChanges();
						this.newTagAddedSubjectService.emit({ poem: this.poem });
						this.poemTagsChangedSubjectService.emit(true);
					},
					error: error => this.alertService.error(error)
				}
			)
		} else {
			this.poemsService.associateWithNewTagName(this.poem.id!, tagName).subscribe(
				{
					next: newTag => {
						if (newTag) {
							this.tagsDic[newTag.id!] = newTag;
							AppCache.tags.unshift(newTag);
							this.poem.tagIds?.push(newTag.id!);
							this.ref.detectChanges();
							this.newTagAddedSubjectService.emit({ poem: this.poem, newTagId: newTag.id! });
							this.poemTagsChangedSubjectService.emit(true);
							this.alertService.success($localize`New tag ${tagName} is added and associated`, true);
						}
					},
					error: error => this.alertService.error(error)
				}
			)
		};
	}

	suggestTags(e: Event) {
		e.stopPropagation();
		const candidates = this.findTagCandidates();
		// then exclude those already associated.
		for (const id of this.poem.tagIds!) {
			const idx = candidates.findIndex(d => d.id === id);
			if (idx >= 0) {
				candidates.splice(idx, 1);
			}
		}

		if (candidates.length > 0) {
			this.tagsSelectionDialogService.open($localize`Tags`, candidates).subscribe(
				rs => {
					if (rs) {
						const ids = rs.map(d => d.id!);
						this.associateExistingTagIdsWithPoem(ids);
					}

				}
			);
		} else {
			this.alertService.warn($localize`Nothing to suggest.`);
		}
	}

	private findTagCandidates() {
		if (AppCache.tags.length > 0) {
			if (this.poemForm.controls.bodyType.value === Fonlow_PoemsApp_Data_Client.BodyType.Text) {
				return AppCache.tags.filter(a => this.noteControl.value.indexOf(a.name) >= 0);
			} else if (this.poemForm.controls.bodyType.value === Fonlow_PoemsApp_Data_Client.BodyType.HTML) {
				const plainText = HtmlFunc.getHtmlPlainText(this.poemForm.controls.body.value);
				return AppCache.tags.filter(a => plainText!.indexOf(a.name!) >= 0);
			} else {
				return AppCache.tags.filter(a => this.noteControl.value.indexOf(a.name) >= 0);
			}
		} else {
			return [];
		}
	}

