import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, Injectable } from '@angular/core';
import { FormBuilder, FormGroup, FormsModule, ReactiveFormsModule, Validators } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialog, MatDialogRef } from '@angular/material/dialog';
import { AngularEditorModule } from '@kolkov/angular-editor';
import { AlertService } from 'nmce';
import { NmceHtmlEditorModule } from 'nmce-html-editor';
import { Observable } from 'rxjs';
import { PoemsApp_Controllers_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { APP_DI_CONFIG } from '../app-config';
import { NGMDModule } from '../ngmd.module';

/**
 * 
 */
@Component({
    selector: 'img-meta',
    templateUrl: 'imgMeta.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [		CommonModule, FormsModule, ReactiveFormsModule,  NGMDModule, AngularEditorModule,
		NmceHtmlEditorModule,
		]
})
export class ImgMetaComponent {
	metaGroup: FormGroup;

	get actionsAlign() {
		return APP_DI_CONFIG.DialogActionsAlign;
	}
	constructor(@Inject(MAT_DIALOG_DATA) private data: {id: string, name: string, description: string},
		private filesService: PoemsApp_Controllers_Client.Files,
		private fb: FormBuilder,
		private alertService: AlertService,
		private dialogRef: MatDialogRef<ImgMetaComponent>,
		private ref: ChangeDetectorRef,
	) {
		this.metaGroup = this.fb.group({
			name: [this.data.name, { validators: [Validators.maxLength(128)] }],
			description: [this.data.description, { validators: [Validators.maxLength(512)] }],
		})
	}

	saveMeta() {
		this.filesService.updateMeta(this.data.id, { item1: this.metaGroup.controls.name.value, item2: this.metaGroup.controls.description.value }).subscribe({
			next: d => {
				this.metaGroup.markAsPristine();
				this.ref.detectChanges();
				this.alertService.success($localize`Saved`);
				this.dialogRef.close({ name: this.metaGroup.controls.name.value, description: this.metaGroup.controls.description.value })
			},
			error: error => this.alertService.error(error)
		});
	}
}

@Injectable()
export class ImgMetaDialogService {
	constructor(private dialog: MatDialog) { }

	open(data: { id: string, name?: string, description?: string }): Observable<{ name: string, description: string }> {
		const modalRef = this.dialog.open(ImgMetaComponent, {
			disableClose: true, autoFocus: false, data: data,
			minWidth: APP_DI_CONFIG.isSmallScreen ? '95vw' : '50vw',
		});
		return modalRef.afterClosed();
	}
}
