import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Injectable, OnInit } from '@angular/core';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { MatDialog, MatDialogRef } from '@angular/material/dialog';
import { AngularEditorModule } from '@kolkov/angular-editor';
import { AlertService, ConfirmService } from 'nmce';
import { NmceHtmlEditorModule } from 'nmce-html-editor';
import { Observable } from 'rxjs';
import { Fonlow_PoemsApp_Data_Client, PoemsApp_Controllers_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { PoemAnnotationsChangedSubjectService, PoemAssociationsChangedSubjectService, SearchByAnnotationSubjectService } from '../_services/types';
import { APP_DI_CONFIG } from '../app-config';
import { AppCache } from '../appCache';
import { NGMDModule } from '../ngmd.module';
import { AnnotationHtmlEditorDialogService } from './annotationHtmlEditor.component';
import { AnnotationsSelectionDialogService } from './annotationsSelectionDialogService';

export interface AnnotationBriefEx extends Fonlow_PoemsApp_Data_Client.AnnotationBrief {
	count?: number | null
}

@Component({
    selector: 'settings-annotations',
    templateUrl: 'settings-annotations.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [		CommonModule, FormsModule, ReactiveFormsModule,  NGMDModule, AngularEditorModule,
		NmceHtmlEditorModule,
		],
		providers: [AnnotationsSelectionDialogService,
			AnnotationHtmlEditorDialogService,
		],
})
export class SettingsAnnotationsComponent implements OnInit {
	get annotations(): AnnotationBriefEx[] {
		return AppCache.annotations as AnnotationBriefEx[];
	}

	get annotationsDic() {
		return AppCache.annotationsDic;
	}

	get clickChipAction() {
		return APP_DI_CONFIG.clickChipActionForAnnotations;
	}
	set clickChipAction(v: number) {
		APP_DI_CONFIG.clickChipActionForAnnotations = v;
	}

	orphansExist = false;

	constructor(
		private dialogRef: MatDialogRef<SettingsAnnotationsComponent>,
		private annotationsService: PoemsApp_Controllers_Client.Annotations,
		private alertService: AlertService,
		private annotationsSelectionDialogService: AnnotationsSelectionDialogService,
		private annotationHtmlEditorDialogService: AnnotationHtmlEditorDialogService,
		private annotationsChangedSubjectService: PoemAnnotationsChangedSubjectService,
		private poemAssociationsChangedSubjectService: PoemAssociationsChangedSubjectService,
		private searchByAnnotationSubjectService: SearchByAnnotationSubjectService,
		private confirmService: ConfirmService,
		private ref: ChangeDetectorRef,
	) {
	}


	ngOnInit(): void {
		this.getPoemCountOfAnnotations();
	}

	private loadAnnotationBriefsWithCount() {
		this.annotationsService.getAnnotationBriefsDic(APP_DI_CONFIG.convertZhHandler).subscribe(
			{
				next: data => {
					if (data) {
						AppCache.annotations = [];
						for (const key in data) {
							AppCache.annotations.push(data[key]); //so both the dic and the list share the same set of Annotation objects
						}

						AppCache.annotationsLoadedSignal.set(true);
						this.getPoemCountOfAnnotations();
					}
				},
				error: error => this.alertService.error(error)
			}
		);
	}

	private getPoemCountOfAnnotations() {
		this.annotationsService.getPoemCountOfAnnotations().subscribe({
			next: cs => {
				for (const c of cs) {
					const a = this.annotationsDic[c.id] as AnnotationBriefEx;
					if (a) {
						a.count = c.count;
					}
				}

				this.orphansExist = cs.length != this.annotations.length;
				this.ref.detectChanges();
			},
			error: error => this.alertService.error(error)
		})
	}

	showOrphanedAnnotations() {
		this.annotationsService.getOrphaned().subscribe({
			next: r => {
				if (r.length == 0) {
					this.alertService.warn($localize`No orphaned annotation.`);
					return;
				}

				this.annotationsSelectionDialogService.open($localize`Orphaned Annotations to Delete`, r).subscribe(
					rs => {
						if (rs) {
							const ids = rs.map(d => d.id);
							if (ids.length > 0) {
								this.annotationsService.deleteOrphaned(ids).subscribe({
									next: c => {
										this.alertService.success($localize`Records deleted: ${c}`, false);
										this.loadAnnotationBriefsWithCount();
									},
									error: error => this.alertService.error(error)
								}
								)
							}
						}

					}
				);
			},
			error: error => this.alertService.error(error)
		}
		)
	}

	removeAnnotation(id: string) {
		this.confirmService.open($localize`Confirm`, $localize`Are you sure to delete?`, $localize`Delete`, $localize`Cancel`).subscribe(
			answer => {
				if (answer) {
					this.annotationsService.delete(id).subscribe({
						next: r => {
							if (r) {
								const idx = this.annotations.findIndex(d => d.id === id);
								if (idx >= 0) {
									this.annotations.splice(idx, 1);
									this.ref.detectChanges();
								}

								this.poemAssociationsChangedSubjectService.emit(true); //tell currentPoem in view to reload
								this.alertService.success($localize`Deleted.`);
							} else {
								this.alertService.warn($localize`Record might had been deleted.`);
							}
						},
						error: error => this.alertService.error(error)
					});
				}
			}
		);
	}

	clickChip(id: string) {
		if (this.clickChipAction === 1) {
			this.editAnnotation(id)
		} else {
			this.searchByAnnotation(id);
		}
	}

	private searchByAnnotation(annotationId: string) {
		this.searchByAnnotationSubjectService.emit(annotationId);
		this.dialogRef.close();
	}

	private editAnnotation(id: string) {
		this.annotationsService.get(id, APP_DI_CONFIG.convertZhHandler).subscribe(
			{
				next: a => {
					if (a) {
						this.annotationHtmlEditorDialogService.open(a).subscribe(
							ra => {
								if (ra) {
									if (ra.name != this.annotationsDic[id].name) {
										this.annotationsDic[id].name = ra.name!;
										this.annotationsChangedSubjectService.emit(true);
										console.debug('Annotation name changed.');
									} else {
										console.debug('Done editing annotation.');
									}
								}
							}
						)
					} else {
						this.alertService.error($localize`Not found. Things may be out of sync.`);
					}
				},
				error: error => this.alertService.error(error)
			}
		);
	}
}

@Injectable()
export class SettingsAnnotationsDialogService {
	constructor(private dialog: MatDialog) { }

	open(): Observable<void> {
		const modalRef = this.dialog.open(SettingsAnnotationsComponent, {
			disableClose: true,
			autoFocus: false,
			minWidth: '98vw',
			minHeight: '98vh',
			panelClass: 'dialog-full-content-height',
		});

		return modalRef.afterClosed();
	}

}
