import { Component, Injectable, OnInit } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { Observable } from 'rxjs';
import { APP_DI_CONFIG } from '../app-config';
import { CommonModule } from '@angular/common';
import { NGMDModule } from '../ngmd.module';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { RegisterComponent } from './register.component';
import { UsersComponent } from './users.component';

@Component({
    selector: 'account-index',
    templateUrl: 'account-index.component.html',
    standalone: true,
	imports: [
		CommonModule,
		FormsModule,
		ReactiveFormsModule,
		NGMDModule,	

		RegisterComponent,
		UsersComponent,

	],
})
export class AccountIndexComponent implements OnInit {
	get isSmallScreen() {
		return APP_DI_CONFIG.isSmallScreen;
	}

	constructor(
	) {

	}
	ngOnInit(): void {
	}
}

@Injectable()
export class AccountDialogService {
	constructor(private dialog: MatDialog) { }

	/**
	 * Display poem object in editor.
	 * @param data
	 */
	open(): Observable<void> {
		const modalRef = this.dialog.open(AccountIndexComponent, {
			disableClose: true,
			autoFocus: false,
			minWidth: '98vw',
			minHeight: '98vh',
			panelClass: 'dialog-full-content-height',
		});

		return modalRef.afterClosed();
	}

}
