import { COMMA, ENTER } from '@angular/cdk/keycodes';
import { CommonModule } from '@angular/common';
import { AfterViewInit, ChangeDetectionStrategy, ChangeDetectorRef, Component, ElementRef, EventEmitter, Inject, Injectable, Input, OnInit, Output, ViewChild } from '@angular/core';
import { FormBuilder, FormControl, FormGroup, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialog, MatDialogRef } from '@angular/material/dialog';
import { AngularEditorComponent, AngularEditorConfig, AngularEditorModule } from '@kolkov/angular-editor';
import { AlertService, ConfirmService } from 'nmce';
import { DateFunc, JsonFunc, StringFunc } from 'nmce-func';
import { NmceHtmlEditorModule } from 'nmce-html-editor';
import { Observable } from 'rxjs';
import { Fonlow_PoemsApp_Data_Client, PoemsApp_Controllers_Client } from 'src/clientapi/WebApiNG2ClientAuto';
import { APP_DI_CONFIG } from '../app-config';
import { AppCache } from '../appCache';
import { NGMDModule } from '../ngmd.module';
import { HtmlEditorMenuComponent } from './htmlEditorMenu.component';

@Component({
    selector: 'album-html-editor',
    templateUrl: './albumHtmlEditor.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [		CommonModule, FormsModule, ReactiveFormsModule,  NGMDModule, AngularEditorModule,
		NmceHtmlEditorModule,
	HtmlEditorMenuComponent,
	]
})
export class AlbumHtmlEditorComponent implements OnInit, AfterViewInit {
	get note() {
		if (!this.noteControl) {
			return '';
		}

		return this.noteControl.value;
	}

	//private _noteControl = new FormControl<string | undefined>('');
	//get noteControl(): FormControl {
	//	return this._noteControl;
	//}
	//set noteControl(v: FormControl) {
	//	this._noteControl = v;
	//}
	get noteControl() {
		return this.albumForm.controls.description;
	}

	get modified(): boolean {
		return this.albumForm.dirty;
	}

	get bodyTypeControl(): FormControl {
		return this.albumForm.controls.bodyType as FormControl;
	}

	private viewPortHeight = Math.max(document.documentElement.clientHeight, window.innerHeight || 0);
	maxRows = (this.viewPortHeight * .90 - 150) / 16;

	/**
	 * Friendly name
	 */
	@Input()
	noteLabel: string;

	@Output()
	modelChanged: EventEmitter<string> = new EventEmitter<string>();

	readonly = false;

	//private viewPortHeight = Math.max(document.documentElement.clientHeight, window.innerHeight || 0);

	config: AngularEditorConfig;
	@ViewChild('htmlEditor') htmlEditor?: AngularEditorComponent;

	albumForm: FormGroup<Fonlow_PoemsApp_Data_Client.AlbumFormProperties>;

	addOnBlur = true;
	readonly separatorKeysCodes = [ENTER, COMMA] as const;

	get defaultPublished(): Date {
		if (this.albumForm.controls.published.value) {
			return this.albumForm.controls.published.value;
		} else {
			return DateFunc.now;
		}
	}

	get maxPublishedDate() {
		return DateFunc.addMonths(DateFunc.now, 12);
	}

	get publishedStartView(): 'month' | 'year' | 'multi-year' {
		if (APP_DI_CONFIG.useYearFirstInPublished) {
			return this.albumForm.controls.published.value ? 'year' : 'multi-year'
		}

		return 'month';
	}

	@ViewChild('albumFormSection') albumFormSection?: ElementRef;

	constructor(
		@Inject(MAT_DIALOG_DATA) public album: Fonlow_PoemsApp_Data_Client.Album,
		public dialogRef: MatDialogRef<AlbumHtmlEditorComponent>,
		//@Inject(HTML_EDITOR_UPLOADURL) private uploadUrl: string | undefined = undefined,
		private alertService: AlertService,
		private albumsService: PoemsApp_Controllers_Client.Albums,
		private fb: FormBuilder,
		private confirmService: ConfirmService,
		private ref: ChangeDetectorRef,
	) {
		this.config = APP_DI_CONFIG.angularEditorConfig;
		if (APP_DI_CONFIG.isChinese) {
			this.config.spellcheck = false;
		}

		this.albumForm = Fonlow_PoemsApp_Data_Client.CreateAlbumFormGroup();
		this.albumForm.patchValue(this.album);
		this.noteLabel = this.album.id ? $localize`Edit` : `Add`;
	}

	//private createAlbumForm() {
	//	return this.fb.group(
	//		{
	//			id: [undefined],
	//			title: [undefined],
	//			description: this.noteControl,
	//			bodyType: [undefined],
	//			published: [undefined],
	//			publishedUrl: [undefined],
	//		}
	//	);
	//}

	/**
	 * For existing, load; for new, if with letterTemplateId, then use the template to render the data and show html generated;
	 * otherwise, show blank HTML doc.
	 */
	ngOnInit(): void {
		this.bodyTypeControl.valueChanges.subscribe(
			(v: Fonlow_PoemsApp_Data_Client.BodyType) => {
				if (this.albumForm.value['bodyType'] == Fonlow_PoemsApp_Data_Client.BodyType.HTML && v == Fonlow_PoemsApp_Data_Client.BodyType.Text) {
					const text = StringFunc.getHtmlPlainText(this.noteControl.value);
					this.noteControl.setValue(text);
				} else if (this.albumForm.value['bodyType'] == Fonlow_PoemsApp_Data_Client.BodyType.Text && v == Fonlow_PoemsApp_Data_Client.BodyType.HTML) {
					const r = this.textToHtmlWithBr(this.noteControl.value);
					this.noteControl.setValue(r);
				}
			}
		)
	}

	ngAfterViewInit() {
		if (this.albumFormSection && APP_DI_CONFIG.defaultWrittenLanguage) {
			this.albumFormSection.nativeElement.lang = APP_DI_CONFIG.defaultWrittenLanguage;
		}
	}

	save() {
		const raw = this.albumForm.getRawValue() as Fonlow_PoemsApp_Data_Client.Album;
		if (this.album.id) {
			console.debug('album to update: ' + raw.description);
			this.albumsService.update(raw).subscribe(
				{
					next: r => {
						this.alertService.success($localize`Updated`, true);
						this.dialogRef.close(raw);
					},
					error: error => this.alertService.error(error)
				}
			)
		} else {
			if (raw.title) {
				const albumNameExists = AppCache.albums.findIndex(d => d.title == this.albumForm.controls.title.value) >= 0;
				if (albumNameExists) {
					this.alertService.warn($localize`Album with the same title exists.`);
				} else {
					JsonFunc.removeNullFields(raw);
					console.debug('album to add: ' + raw.description);
					this.albumsService.add(raw).subscribe(
						{
							next: newAlbum => {
								this.alertService.success($localize`Added`, true);
								this.dialogRef.close(newAlbum);
							},
							error: error => this.alertService.error(error)
						}
					);
				}
			} else {
				this.alertService.warn($localize`Please give the album a title`);
			}
		}

		//this.dialogRef.close(undefined);
	}

	reset() {
		if (this.album.id) {
			this.albumsService.get(this.album.id, APP_DI_CONFIG.convertZhHandler).subscribe(
				{
					next: r => {
						if (r) {
							this.album = r;
							this.albumForm.reset(undefined);
							this.albumForm.patchValue(r); // this.noteControl is included inside
							this.ref.detectChanges();
						} else {
							this.alertService.warn($localize`Not found`);
						}
					},
					error: error => this.alertService.error(error)
				}
			)
		} else {
			this.album = { bodyType: Fonlow_PoemsApp_Data_Client.BodyType.HTML };
			this.albumForm.reset(undefined);
			this.albumForm.patchValue(this.album);
		}
	}

	close() {
		if (this.albumForm.dirty) {
			this.confirmService.open($localize`Quit Editing`, $localize`The record is altered. Are you sure to quit without saving?`, $localize`Quit`, $localize`Stay`).subscribe(
				r => {
					if (r) {
						this.dialogRef.close();
					}
				}
			);
		} else {
			this.dialogRef.close();
		}
	}

	//print() {
	//	if (!this.noteControl.value) {
	//		this.alertService.warn('Not allow to print empty document.');
	//		return;
	//	}

	//	HtmlPrintFunc.print(this.noteControl.value);
	//}

	private textToHtmlWithBr(s: string | null | undefined) {
		if (!s) {
			return s;
		}

		if (s.indexOf('\n') < 0) {
			return s
		}

		const r1 = s.replaceAll('\r\n', '<br>');
		const r2 = r1.replaceAll('\n', '<br>');
		return r2;
	}
}

@Injectable()
export class AlbumHtmlEditorDialogService {
	constructor(private dialog: MatDialog) { }

	/**
	 * Display HTML document or create new HTML document with a template
	 * @param data
	 */
	open(data: Fonlow_PoemsApp_Data_Client.Album): Observable<Fonlow_PoemsApp_Data_Client.Album> {
		const modalRef = this.dialog.open(AlbumHtmlEditorComponent, {
			disableClose: true,
			autoFocus: false,
			minWidth: '98vw',
			minHeight: '98vh',
			panelClass: 'dialog-full-content-height',
			data: data,
		});

		return modalRef.afterClosed();
	}

}

