import { Component, OnInit } from '@angular/core';
import { AlertService, NmceComponentsModule, WaitService } from 'nmce';
import { Fonlow_AspNetCore_Identity_Client, Fonlow_Auth_Controllers_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { CommonModule } from '@angular/common';
import { NGMDModule } from '../ngmd.module';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { RolesComponent } from './roles.component';

/**
 * Fill up the user registration form and register. Then roles checkboxes will appear.
 * and the Register button may become disabled when the user is just registered.
 */
@Component({
    selector: 'account-register',
    templateUrl: 'register.component.html',
    standalone: true,
	imports: [
		CommonModule,
		FormsModule,
		ReactiveFormsModule,
		NGMDModule,	

		RolesComponent,
	],
})
export class RegisterComponent implements OnInit {
	model: Fonlow_AspNetCore_Identity_Client.RegisterBindingModel = {};
	loading = false;
	userId?: string;
	submitted?: boolean;
	hide = true;
	constructor(
		private service: Fonlow_Auth_Controllers_Client.Account,
		private alertService: AlertService,
		private waitService: WaitService,
		) {
	}

	ngOnInit() {
		this.clear();
	}

	register() {
		this.loading = true;
		this.waitService.setWait({ loading: true });
		this.model.confirmPassword = this.model.password;
		this.service.register(this.model).subscribe(
			{
				next: data => {
					this.userId = data;
					this.alertService.success($localize`Registration successful for ${this.model.userName}`, true);
					this.loading = false;
					this.waitService.setWait({ loading: false });
					this.submitted = true;
					if (this.model.email) {
						this.alertService.success($localize`Registration successful for ${this.model.userName}. And a confirmation Email will be sent to the account holder to confirm the Email address.`, true);
					} else {
						this.alertService.success($localize`Registration successful for ${this.model.userName}`, true);
					}
				},
				error: error => {
					this.alertService.error(error);
					this.loading = false;
					this.waitService.setWait({ loading: false });
				}
			});
	}

	clear() {
		this.userId = undefined;
		this.submitted = false;
	}

}
