import { CommonModule } from '@angular/common';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { AfterViewInit, ChangeDetectionStrategy, ChangeDetectorRef, Component, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { ActivatedRoute } from '@angular/router';
import { AngularEditorModule } from '@kolkov/angular-editor';
import { DateTime } from 'luxon';
import { AlertService, ConfirmService, WaitService } from 'nmce';
import { NmceHtmlEditorModule } from 'nmce-html-editor';
import { catchError, fromEvent, Subject, takeUntil, throwError } from 'rxjs';
import { FilesDownload } from '../../clientapi/FilesDownload';
import { Fonlow_PoemsApp_Data_Client, PoemsApp_Controllers_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { AuthServicesModule } from '../_authServices/authServices.module';
import { LogoutService } from '../_authServices/logout.service';
import { AUTH_STATUSES } from '../_authServices/tokenInterceptor';
import { ConfirmUploadService } from '../_services/confirmUpload.component';
import { LangSubjectService, NewPoemAddedSubjectService, NewTagAddedSubjectService, PoemDeletedSubjectService, PoemModifiedSubjectService, SearchByAnnotationSubjectService } from '../_services/types';
import { AccountDialogService } from '../account/account-index.component';
import { APP_DI_CONFIG } from '../app-config';
import { AppCache } from '../appCache';
import { NGMDModule } from '../ngmd.module';
import { AboutDialogService } from '../shared/about.component';
import { AllMetaServiceModule } from '../shared/allMetaService.module';
import { BasicDataLoaderService } from '../shared/basicDataLoader.service';
import { MainButtonsComponent } from "../shared/main-buttons.component";
import { MainComponentBase } from '../shared/mainBase.directive';
import { AlbumHtmlEditorDialogService } from './albumHtmlEditor.component';
import { AlbumSelectionDialogService } from './albumSelectionDialogService';
import { AnnotationHtmlEditorDialogService } from './annotationHtmlEditor.component';
import { AnnotationsSelectionDialogService } from './annotationsSelectionDialogService';
import { ChronicleForEditorComponent } from './chronicle-for-editor.component';
import { ImgMetaDialogService } from './imgMeta.component';
import { NumberedAnnotationHtmlEditorDialogService } from './numberedAnnotationHtmlEditor.component';
import { NumberedAnnotationsSelectionDialogService } from './numberedAnnotationsSelectionDialogService';
import { PoemHtmlEditorDialogService } from './poemHtmlEditor.component';
import { SettingsAnnotationsDialogService } from './settings-annotations.component';
import { SettingsFilesDialogService } from './settings-files.component';
import { SettingsDialogService } from './settings-index.component';
import { SettingsNotLocalImagesDialogService } from './settings-not-local-images.component';
import { SettingsTagsDialogService } from './settings-tags.component';
import { TagsSelectionDialogService } from './tagsSelectionDialogService';

@Component({
	selector: 'main-for-editor',
	templateUrl: './main-for-editor.component.html',
	styles: [''],
	standalone: true,
	changeDetection: ChangeDetectionStrategy.OnPush,
	imports: [CommonModule, FormsModule, ReactiveFormsModule, NGMDModule, AngularEditorModule,
		NmceHtmlEditorModule, AllMetaServiceModule, AuthServicesModule,
		ChronicleForEditorComponent, MainButtonsComponent],
	providers: [PoemHtmlEditorDialogService,
		AlbumHtmlEditorDialogService,
		AnnotationHtmlEditorDialogService,
		AnnotationsSelectionDialogService,
		TagsSelectionDialogService,
		NumberedAnnotationsSelectionDialogService,
		NumberedAnnotationHtmlEditorDialogService,
		SettingsDialogService,
		SettingsAnnotationsDialogService,
		SettingsTagsDialogService,
		SettingsFilesDialogService,
		SettingsNotLocalImagesDialogService,
		AlbumSelectionDialogService,
		ImgMetaDialogService, AccountDialogService,
		BasicDataLoaderService,
		AboutDialogService,
	]
})
export class MainForEditorComponent extends MainComponentBase implements OnInit, OnDestroy, AfterViewInit {
	private unsubscriber: Subject<void> = new Subject<void>();

	get loggedIn() {
		return AUTH_STATUSES.loggedIn;
	}

	@ViewChild('chronicle') chronicleForEditor?: ChronicleForEditorComponent;

	private unsubscribe: Subject<void> = new Subject();

	get useAlbums() {
		return APP_DI_CONFIG.useAlbums;
	}

	get hasAlbums() {
		return AppCache.albums?.length > 0;
	}

	get isChinese() {
		return APP_DI_CONFIG.defaultWrittenLanguage.indexOf('zh-') >= 0;
	}

	get sOrT() {
		return APP_DI_CONFIG.sOrT;
	}

	get usePublished() {
		return APP_DI_CONFIG.usePublished;
	}

	get useAnnotations() {
		return APP_DI_CONFIG.useAnnotations;
	}

	get useTags() {
		return APP_DI_CONFIG.useTags;
	}

	menuTextOfExport2nd = '';

	constructor(
		protected activatedRoute: ActivatedRoute,
		protected alertService: AlertService,
		protected tagsSerrvice: PoemsApp_Controllers_Client.Tags,
		protected albumsService: PoemsApp_Controllers_Client.Albums,
		protected annotationsService: PoemsApp_Controllers_Client.Annotations,
		protected poemsService: PoemsApp_Controllers_Client.Poems,
		protected keyValuesService: PoemsApp_Controllers_Client.KeyValues,
		protected basicDataLoaderService: BasicDataLoaderService,
		protected langSubjectService: LangSubjectService,
		protected waitService: WaitService,

		private settingsDialogService: SettingsDialogService,
		private settingsAnnotationsDialogService: SettingsAnnotationsDialogService,
		private settingsTagsDialogService: SettingsTagsDialogService,
		private settingsFilesDialogService: SettingsFilesDialogService,
		private settingsExternalImagesDialogService: SettingsNotLocalImagesDialogService,
		private accountDialogService: AccountDialogService,
		private newPoemAddedSubjectService: NewPoemAddedSubjectService,
		private poemModifiedSubjectService: PoemModifiedSubjectService,
		private newTagAddedSubjectService: NewTagAddedSubjectService,
		private searchByAnnotationSubjectService: SearchByAnnotationSubjectService,
		private poemHtmlEditorDialogService: PoemHtmlEditorDialogService,
		private poemDeletedSubjectService: PoemDeletedSubjectService,
		private filesDownload: FilesDownload,
		private confirmUploadService: ConfirmUploadService,
		private confirmService: ConfirmService,
		private httpClient: HttpClient,
		private logoutService: LogoutService,
		private aboutService: AboutDialogService,
		private ref: ChangeDetectorRef,
	) {
		super(activatedRoute, alertService, basicDataLoaderService, langSubjectService, waitService);

		console.debug('MainComponent created. IsSmallScreen: ' + this.isSmallScreen);
		this.newTagAddedSubjectService.getMessage().pipe(takeUntil(this.unsubscribe)).subscribe(
			r => {
				const poemBrief = this.poemBriefs.find(d => d.id === r.poem.id);
				if (poemBrief) {
					poemBrief.tagIds = r.poem.tagIds;
					this.ref.detectChanges();
				}
			}
		);

		this.poemDeletedSubjectService.getMessage().pipe(takeUntil(this.unsubscribe)).subscribe(
			id => {
				const idx = this.poemBriefs.findIndex(d => d.id === id);
				if (idx >= 0) {
					this.poemBriefs.splice(idx, 1);
					this.ref.detectChanges();
				}
			}
		);

		this.newPoemAddedSubjectService.getMessage().pipe(takeUntil(this.unsubscribe)).subscribe(
			r => {
				const brief: Fonlow_PoemsApp_Data_Client.PoemBrief = {
					id: r.id!,
					title: r.title!,
					date: r.modified!,
					published: r.published,
					tagIds: r.tagIds,
				};

				this.poemBriefs.unshift(brief);
				if (this.chronicle && this.chronicle.filteredPoemBriefs.findIndex(d => d.id === brief.id) < 0) { //add only if not found. Sometimes this.filteredPoemBriefs is poemBriefs.
					this.chronicle.filteredPoemBriefs.unshift(brief);
				}

				this.ref.detectChanges();
			}
		);

		this.poemModifiedSubjectService.getMessage().pipe(takeUntil(this.unsubscribe)).subscribe(
			r => {
				if (r) {
					const poemBrief = this.poemBriefs.find(d => d.id === r.id);
					if (poemBrief) {
						poemBrief.title = r.title!;
						poemBrief.date = r.modified!;
						poemBrief.published = r.published;
						poemBrief.tagIds = r.tagIds;
					}
				}

				this.ref.detectChanges();
			}
		);

		this.searchByAnnotationSubjectService.getMessage().pipe(takeUntil(this.unsubscribe)).subscribe(
			id => {
				this.searchByAnnotation(id);
			}
		);

		if (APP_DI_CONFIG.usePublished) {
			this.menuTextOfExport2nd = APP_DI_CONFIG.defaultWrittenLanguage === 'zh-Hans' ? $localize`Export All Published in Traditional Chinese` : $localize`Export All Published in Simplified Chinese`;
		} else {
			this.menuTextOfExport2nd = APP_DI_CONFIG.defaultWrittenLanguage === 'zh-Hans' ? $localize`Export All in Traditional Chinese` : $localize`Export All in Simplified Chinese`;
		}
	}

	ngOnInit(): void {
		history.pushState(null, ''); //disable back

		fromEvent(window, 'popstate').pipe(
			takeUntil(this.unsubscriber)
		).subscribe((_) => {
			history.pushState(null, '');
			console.debug(`Not allow to go back to login`);
		});

		this.reload();
	}

	ngOnDestroy(): void {
		this.unsubscribe.next();
		this.unsubscribe.complete();

		this.unsubscriber.next();
		this.unsubscriber.complete();
		console.debug('MainForEditorComponent destroyed');
	}

	ngAfterViewInit(): void {
		super.ngAfterViewInitShared();
		console.debug('MainComponent ngAfterViewInit');
		//setTimeout(() => this.multipleTagsControl.setValue(false), 300);
		//there seems a bug in chipList. I have to init it to true first, then I can toggle true and false.
		//otherwise, when switching to true, chips always has 1 element. 200ms delay is to ensure going around the bug.
		//todo: report to NG team later.
		this.loading = false;
		this.ref.detectChanges();
	}

	protected loadBriefs() {
		this.poemsService.getBriefsOfPoems(APP_DI_CONFIG.convertZhHandler).subscribe(
			{
				next: data => {
					if (data) {
						if (!APP_DI_CONFIG.usePublished) {
							data.sort((x, y) => x.title!.localeCompare(y.title!, APP_DI_CONFIG.defaultWrittenLanguage)); //for zh-Hans, Pinyin, for zh-Hant, number of stokes.
						}

						if (this.loggedIn) {
							const unpublishedOnTop = data.sort((a, b) => { //make sure the unpublished on the top, and the published poems are decending sorted by published date.
								if (a.published && !b.published) {
									return 1;
								} else if (!a.published && b.published) {
									return -1;
								} else if (!a.published && !b.published) {
									if (a.date < b.date) {
										return -1
									} else if (a.date > b.date) {
										return 1
									} else {
										return 0;
									}
								} else { //both published
									if (a.published! < b.published!) {
										return 1
									} else if (a.published! > b.published!) {
										return -1
									} else {
										return 0;
									}
								}
							});

							this.poemBriefs = unpublishedOnTop;
						} else {
							this.poemBriefs = data;
						}

						this.poemsLoadedSignal.set(true);
						this.chronicle!.listAllPoemBriefs();
						this.ref.detectChanges();
						this.waitService.setWait({ loading: false });
					}
				},
				error: error => {
					this.alertService.error(error);
					this.waitService.setWait({ loading: false });
				}
			}
		);
	}

	addPoem() {
		const newPoem: Fonlow_PoemsApp_Data_Client.Poem = {
			bodyType: Fonlow_PoemsApp_Data_Client.BodyType.HTML,
			tagIds: [],
			albumIds: [],
			annotationIds: [],
			numberedAnnotationBriefs: [],
		};

		if (!APP_DI_CONFIG.usePublished) {
			newPoem.published = new Date('0001-01-01T00:00:00Z'); //C# min date
		}

		this.poemHtmlEditorDialogService.open({ poem: newPoem, poemBriefs: this.poemBriefs }).subscribe();
	}

	searchByAnnotation(annotationId: string) {
		this.poemsService.searchByAnnotation(annotationId).subscribe({
			next: r => {
				if (r.length > 0) {
					this.chronicle!.filteredPoemBriefs = r;
					this.ref.detectChanges();
					this.alertService.info($localize`Found: ` + r.length, false);
				} else {
					this.alertService.warn($localize`No poem with this annotation.`);
				}
			},
			error: error => this.alertService.error(error)
		})
	}

	private handleCollection(collection: Fonlow_PoemsApp_Data_Client.PoemCollection, filename: string) {
		const myFile = new Blob([JSON.stringify(collection)], { type: 'text/json' });
		const url = window.URL || window.webkitURL;
		const fileURL = url.createObjectURL(myFile);
		const a = document.createElement('a');
		a.href = fileURL;
		a.download = filename;
		a.click();
	}

	saveCollection() {
		this.poemsService.getPoemCollection().subscribe(
			{
				next: collection => {
					this.handleCollection(collection, `PoetryAll${this.getDateStamp()}.json`);
				},
				error: error => this.alertService.error(error)
			}
		);
	}

	getDateStamp() {
		return DateTime.now().toISODate();
	}

	saveCollectionPublished() {
		const offsetMinutes = -new Date().getTimezoneOffset()
		const headers = new HttpHeaders();
		headers.append('timezoneOffset', offsetMinutes.toString());
		this.poemsService.getPoemCollectionPublished(() => headers).subscribe(
			{
				next: collection => {
					this.handleCollection(collection, `PoetryPublished${this.getDateStamp()}.json`);
				},
				error: error => this.alertService.error(error)
			}
		);
	}

	saveCollectionSOrT() {
		const offsetMinutes = -new Date().getTimezoneOffset()
		const headers = new HttpHeaders({ 'timezoneOffset': offsetMinutes.toString() });
		const api = APP_DI_CONFIG.usePublished ? this.poemsService.getPoemCollectionPublishedInOtherChineseWriting(() => headers) : this.poemsService.getPoemCollectionInOtherChineseWriting();
		api.subscribe(
			{
				next: collection => {
					if (collection) {
						const filename = APP_DI_CONFIG.usePublished ? `PoetryPublished2nd${this.getDateStamp()}.json` : `PoetryAll2nd${this.getDateStamp()}.json`;
						this.handleCollection(collection, filename);
					} else {
						this.alertService.warn($localize`No collection return probably due to invalid config.`);
					}
				},
				error: error => this.alertService.error(error)
			}
		);
	}

	downloadImages() {
		this.filesDownload.getAllImagesInZip().subscribe({
			next: bytes => {
				const blob = new Blob([bytes], { type: 'application/zip' });
				const a = document.createElement('a');
				a.href = window.URL.createObjectURL(blob);
				a.download = `AllImages${this.getDateStamp()}.zip`;
				a.click();

			},
			error: error => this.alertService.error(error)
		});
	}

	/**
	 * This is just for maintenance during development. Nomally the HTML UI hide this command.
	 */
	updatePlainText() {
		this.poemsService.updatePlainTextOfHtmlPoems().subscribe({
			next: r => {
				this.alertService.success($localize`Done`);
			},
			error: error => this.alertService.error(error)
		});
	}

	showSettings() {
		this.settingsDialogService.open().subscribe();
	}

	showSettingsAnnotations() {
		this.loadAnnotationBriefs(() => this.settingsAnnotationsDialogService.open().subscribe())
	}

	showSettingsTags() {
		this.loadTags(() => this.settingsTagsDialogService.open().subscribe())
	}

	showSettingsPictures() {
		this.loadTags(() => this.settingsFilesDialogService.open({ poemBriefs: this.poemBriefs, selectionMode: false }).subscribe())
	}

	showSettingsExternalPictures() {
		this.loadTags(() => this.settingsExternalImagesDialogService.open({ poemBriefs: this.poemBriefs, selectionMode: false }).subscribe())
	}

	showUsers() {
		this.accountDialogService.open().subscribe();
	}

	editCurrentPoem() {
		this.chronicleForEditor?.edit();
	}

	deleteCurrentPoem() {
		this.chronicleForEditor?.delete();
	}

	defineCurrentAlbum() {
		this.chronicleForEditor?.defineCurrentAlbum();
	}

	showAbout() {
		this.aboutService.open().subscribe();
	}

	help() {
		window.open('https://poetryappwiki.fonlow.org/wiki/User_Manual', '_blank');
	}

	import() {
		this.confirmUploadService.open($localize`Import`, $localize`Select JSON file`, '.json').subscribe(
			brief => {
				if (brief && brief.file) {
					const reader = new FileReader();
					reader.onload = () => {
						if (reader.result) {
							const collection = JSON.parse(<string>reader.result);
							this.poemsService.importPoemCollection(collection).subscribe({
								next: r => {
									this.alertService.success($localize`Done. Please logout later to reload.`, false);
								},
								error: error => this.alertService.error(error)
							})
						}
					};

					reader.readAsText(brief.file!);
				}
			}
		);
	}

	private uploadFilesInZip(formData: FormData) {
		const headers = new HttpHeaders();
		/** No need to include Content-Type in Angular 4 */
		headers.append('Content-Type', 'multipart/form-data');
		headers.append('Accept', 'application/json');

		// this.filesService.uploadAvatar(this.model.id);
		this.waitService.setWait({ loading: true });
		const url = APP_DI_CONFIG.apiBaseUri + 'api/upload/uploadFilesInZip';
		this.httpClient.post(url, formData, { headers: headers }).pipe(catchError(error => throwError(error))).subscribe(
			{
				next: () => {
					this.waitService.setWait({ loading: false });
					this.alertService.success($localize`Done`, true);
				},
				error: error => {
					this.waitService.setWait({ loading: false });
					this.alertService.error(error);
				}
			}
		);

	}

	importZip() {
		this.confirmUploadService.open($localize`Import`, $localize`Select Zip file`, '.zip').subscribe(
			brief => {
				if (brief && brief.file) {
					const formData: FormData = new FormData();
					formData.append('files', brief.file!, brief.file?.name);
					this.uploadFilesInZip(formData);
				}
			}
		);
	}

	clearDatabase() {
		this.confirmService.open($localize`Warning`, $localize`This will clear all contents and settings, and the app will logout after the clearing. Do you want to clear all?`,
			$localize`Yes`, $localize`No`).subscribe(
				r => {
					if (r) {
						this.poemsService.clearAllTables().subscribe(
							{
								next: d => {
									this.alertService.success('Contents and settings removed. Now being logged out...');
									this.logoutService.logout().subscribe(
										() => {
											this.ref.detectChanges();
										});
									APP_DI_CONFIG.sOrT = undefined;
									APP_DI_CONFIG.defaultWrittenLanguage = 'en';
									APP_DI_CONFIG.currentZhWritten = undefined;
									this.reload();
								},
								error: error => this.alertService.error(error)
							}
						);
					}
				}
			);
	}
}
