import { ScrollDispatcher } from '@angular/cdk/scrolling';
import { CommonModule, Location } from '@angular/common';
import { HttpHeaders } from '@angular/common/http';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, OnDestroy, ViewChild } from '@angular/core';
import { FormControl, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { MatSelectionList } from '@angular/material/list';
import { Title } from '@angular/platform-browser';
import { ActivatedRoute, Router } from '@angular/router';
import { AngularEditorModule } from '@kolkov/angular-editor';
import { AlertService, ConfirmService, DataComponentDialogService } from 'nmce';
import { NmceHtmlEditorModule } from 'nmce-html-editor';
import { Subject, takeUntil } from 'rxjs';
import { Fonlow_PoemsApp_Data_Client, PoemsApp_Controllers_Client } from 'src/clientapi/WebApiNG2ClientAuto';
import { EditPoemSubjectService, LangSubjectService, NewPoemAddedSubjectService, PoemAssociationsChangedSubjectService, PoemDeletedSubjectService, PoemModifiedSubjectService } from '../_services/types';
import { AppCache } from '../appCache';
import { NGMDModule } from '../ngmd.module';
import { ChronicleViewComponentBase } from '../shared/chronicleBase.directive';
import { PoemViewerComponent } from "../shared/poemViewer.component";
import { AlbumSelectionDialogService } from './albumSelectionDialogService';
import { PoemHtmlEditorDialogService } from './poemHtmlEditor.component';

@Component({
	selector: 'chronicle-for-editor',
	templateUrl: './chronicle-for-editor.component.html',
	changeDetection: ChangeDetectionStrategy.OnPush,
	standalone: true,
	imports: [CommonModule, FormsModule, ReactiveFormsModule, NGMDModule, AngularEditorModule,
		NmceHtmlEditorModule, PoemViewerComponent]
})
export class ChronicleForEditorComponent extends ChronicleViewComponentBase implements OnDestroy {
	selectionMode = new FormControl(false);

	@ViewChild('poemsSelectionList') poemsSelectionList?: MatSelectionList;

	get selectedPoemIds(): string[] {
		if (this.poemsSelectionList) {
			return this.poemsSelectionList.selectedOptions.selected.map(d => d.value);
		} else {
			return []
		}
	}

	currentAlbum?: Fonlow_PoemsApp_Data_Client.Album;

	get selectAlbumLabel() {
		return this.currentAlbum ? $localize`Unselect Album` : $localize`Select Album`;
	}

	poemIdsOfCurrentAlbum: string[] = [];

	private unsubscribe: Subject<void> = new Subject();

	constructor(
		protected router: Router,
		protected location: Location,
		protected activatedRoute: ActivatedRoute,
		protected poemsService: PoemsApp_Controllers_Client.Poems,
		protected alertService: AlertService,
		protected dataComponentDialogService: DataComponentDialogService,
		protected poemDeletedSubjectService: PoemDeletedSubjectService,
		protected poemAssociationsChangedSubjectService: PoemAssociationsChangedSubjectService,
		protected poemHtmleditorService: PoemHtmlEditorDialogService,
		protected confirmService: ConfirmService,
		protected albumSelectionDialogService: AlbumSelectionDialogService,
		protected langSubjectService: LangSubjectService,
		protected title: Title,
		protected ref: ChangeDetectorRef,
		protected scrollDispatcher: ScrollDispatcher,
		private editPoemSubjectService: EditPoemSubjectService,
		private poemModifiedSubjectService: PoemModifiedSubjectService,
		private newPoemAddedSubjectService: NewPoemAddedSubjectService,

	) {
		console.debug('ChronicleViewExComponent created.');
		super(router, location, activatedRoute, poemsService, alertService, dataComponentDialogService, langSubjectService, title, ref, scrollDispatcher)

		this.poemDeletedSubjectService.getMessage().pipe(takeUntil(this.unsubscribe)).subscribe(
			id => {
				const idx = this.filteredPoemBriefs.findIndex(d => d.id === id);
				if (idx >= 0) {
					this.filteredPoemBriefs.splice(idx, 1);
					this.currentPoem = {};
					this.ref.detectChanges();
				}
			}
		);

		this.poemAssociationsChangedSubjectService.getMessage().pipe(takeUntil(this.unsubscribe)).subscribe(
			r => {
				if (this.currentPoem != null && this.currentPoem.id) {
					this.loadPoem(this.currentPoem.id);
				}
			}
		);

		this.editPoemSubjectService.getMessage().pipe(takeUntil(this.unsubscribe)).subscribe(
			id => {
				this.editPoem(id);
			}
		);

		this.poemModifiedSubjectService.getMessage().pipe(takeUntil(this.unsubscribe)).subscribe(
			r => {
				if (r && this.currentPoem.id === r.id) {
					this.currentPoem = r;
				}

				this.ref.detectChanges();
			}
		);

		this.newPoemAddedSubjectService.getMessage().pipe(takeUntil(this.unsubscribe)).subscribe(
			r => {
				this.ref.detectChanges();
			}
		);

	}

	ngOnDestroy() {
		this.unsubscribe.next();
		this.unsubscribe.complete();
		super.ngOnDestroy();
	}

	edit() {
		this.poemHtmleditorService.open({ poem: this.currentPoem, poemBriefs: this.poemBriefs }).subscribe();
	}

	editPoem(poemId: string) {
		this.poemsService.get(poemId).subscribe(
			{
				next: ps => {
					if (ps) {
						ps.numberedAnnotationBriefs?.sort((a, b) => a.orderNumber - b.orderNumber);
						this.poemHtmleditorService.open({ poem: ps, poemBriefs: this.poemBriefs }).subscribe();
						this.ref.detectChanges();
					}
				},
				error: error => this.alertService.error(error)
			}
		);
	}

	delete() {
		this.confirmService.open($localize`Deleting`, $localize`Are you sure to delete ${this.currentPoem.title}?`).subscribe(
			r => {
				if (r) {
					this.poemsService.delete(this.currentPoem.id!).subscribe(
						{
							next: result => {
								if (r) {
									this.poemDeletedSubjectService.emit(this.currentPoem.id!);
								} else {
									this.alertService.warn($localize`Not found`);
								}
							},
							error: error => this.alertService.error(error)
						}
					)
				}
			}
		)

	}

	defineCurrentAlbum() {
		if (!this.currentAlbum) {
			this.albumSelectionDialogService.openForSingle($localize`Select album for a collection of poems`, AppCache.albums).subscribe(
				a => {
					if (a) {
						this.currentAlbum = a;
						this.selectionMode.setValue(true);
						const offsetMinutes = -new Date().getTimezoneOffset()
						const headers = new HttpHeaders({ 'timezoneOffset': offsetMinutes.toString() });
						this.poemsService.getPoemBriefsOfAlbum(a.id, () => headers).subscribe({
							next: poems => {
								this.poemIdsOfCurrentAlbum = poems.map(d => d.id);
								if (this.poemsSelectionList) {
									for (const option of this.poemsSelectionList.options) {
										if (poems.findIndex(d => d.id === option.value) >= 0) {
											option.selected = true;
										}
									}

									this.ref.detectChanges();
								}
							}
						});
					}
				}
			);
		} else {
			this.currentAlbum = undefined;
			this.selectionMode.setValue(false);
			this.ref.detectChanges();
		}
	}

	/**
	 * Triggered when the item is selected, through UX or programming.
	 * @param selected
	 * @param poemId
	 */
	handlePoemItemSelectedChange(selected: boolean, poemId: string) {
		if (selected) {
			const alreadyInAlbum = this.poemIdsOfCurrentAlbum.indexOf(poemId) >= 0;
			if (!alreadyInAlbum) {
				this.loadPoem(poemId);
				this.poemsService.associateWithAlbums(poemId, [this.currentAlbum?.id!]).subscribe({
					next: r => {
						this.poemIdsOfCurrentAlbum.push(poemId);
						this.ref.detectChanges();
						this.alertService.success($localize`Added`, true);
					},
					error: error => this.alertService.error(error)
				});
			}
		} else {
			this.loadPoem(poemId);
			this.poemsService.dissociateAlbum(poemId, this.currentAlbum?.id!).subscribe({
				next: r => {
					const idx = this.poemIdsOfCurrentAlbum.indexOf(poemId);
					if (idx >= 0) {
						this.poemIdsOfCurrentAlbum.splice(idx, 1);
						this.ref.detectChanges();
						this.alertService.info($localize`Removed`, true);
					}
				},
				error: error => this.alertService.error(error)
			});
		}
	}
}
