import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, Injectable, OnInit } from '@angular/core';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialog, MatDialogRef } from '@angular/material/dialog';
import { AngularEditorModule } from '@kolkov/angular-editor';
import { AlertService, ConfirmService } from 'nmce';
import { NmceHtmlEditorModule } from 'nmce-html-editor';
import { Observable } from 'rxjs';
import { Fonlow_PoemsApp_Data_Client, PoemsApp_Controllers_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { EditPoemSubjectService, PictureBriefEx } from '../_services/types';
import { APP_DI_CONFIG } from '../app-config';
import { NGMDModule } from '../ngmd.module';
import { ImgMetaDialogService } from './imgMeta.component';


@Component({
    selector: 'settings-files',
    templateUrl: 'settings-files.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [		CommonModule, FormsModule, ReactiveFormsModule,  NGMDModule, AngularEditorModule,
		NmceHtmlEditorModule,
		],
		providers: [ImgMetaDialogService]
})
export class SettingsFilesComponent implements OnInit {
	pictures: PictureBriefEx[] = [];
	picturesDic: { [id: string]: Fonlow_PoemsApp_Data_Client.Picture } = {};

	poemBriefsDic: { [id: string]: Fonlow_PoemsApp_Data_Client.PoemBrief };

	orphansExist = false;

	selectedFiles: PictureBriefEx[] = [];

	constructor(
		@Inject(MAT_DIALOG_DATA) public data: { poemBriefs: Fonlow_PoemsApp_Data_Client.PoemBrief[], selectionMode: boolean, imgIds?: string[] },
		private dialogRef: MatDialogRef<SettingsFilesComponent>,
		private poemsService: PoemsApp_Controllers_Client.Poems,
		private picturesService: PoemsApp_Controllers_Client.Files,
		private alertService: AlertService,
		private editPoemSubjectService: EditPoemSubjectService,
		private imgMetaDialogService: ImgMetaDialogService,
		private confirmService: ConfirmService,
		private ref: ChangeDetectorRef,
	) {
		this.poemBriefsDic = Object.assign({}, ...data.poemBriefs.map((x) => ({ [x.id!]: x }))); // array to dic
	}


	ngOnInit(): void {
		this.loadPictureBriefsWithCount();
	}

	private loadPictureBriefsWithCount() {
		this.picturesService.getPicturesDic().subscribe(
			{
				next: data => {
					if (data) {
						this.picturesDic = data;
						this.pictures = [];
						for (const key in data) {
							this.pictures.push(data[key]); //so both the dic and the list share the same set of Picture objects
						}

						this.ref.detectChanges();
						this.getPoemCountOfPictures();
					}
				},
				error: error => this.alertService.error(error)
			}
		);
	}

	private getPoemCountOfPictures() {
		this.picturesService.getPoemCountOfPictures().subscribe({
			next: cs => {
				for (const c of cs) {
					const a = this.picturesDic[c.id] as PictureBriefEx;
					if (a) {
						a.count = c.count;
						a.poemIds = c.poemIds;
					}
				}

				this.orphansExist = cs.length != this.pictures.length;
				this.ref.detectChanges();
			},
			error: error => this.alertService.error(error)
		})
	}

	buildImgSrc(imgMeta: PictureBriefEx) {
		const ss = imgMeta.contentType?.split('/');
		if (ss && ss.length > 1) {
			return `${APP_DI_CONFIG.apiBaseUri}api/files/file/${imgMeta.id}.${ss[1]}`;
		} else {
			const ff = imgMeta.name?.split('/');
			if (ff && ff.length > 1) {
				return `${APP_DI_CONFIG.apiBaseUri}api/files/file/${imgMeta.id}.${ff[ff.length - 1]}`;
			}
		}

		return `${APP_DI_CONFIG.apiBaseUri}api/files/file/${imgMeta.id}`;
	}

	deleteFile(fileId: string) {
		this.picturesService.delete(fileId).subscribe({
			next: r => {
				if (r) {
					const idx = this.pictures.findIndex(d => d.id === fileId);
					if (idx >= 0) {
						this.pictures.splice(idx, 1);
					}

					this.ref.detectChanges();

					this.alertService.success($localize`Deleted`);
				} else {
					this.alertService.warn($localize`Something wrong when deleting.`);
				}
			},
			error: error => this.alertService.error(error)
		}
		)
	}

	editPoem(poemId: string) {
		this.editPoemSubjectService.emit(poemId);
	}

	pickOrUnpick(toPick: boolean, pic: PictureBriefEx) {
		const idx = this.selectedFiles.findIndex(d => d.id === pic.id);
		if (toPick) {
			if (idx < 0) {
				this.selectedFiles.push(pic);
			}
		} else {
			if (idx >= 0) {
				this.selectedFiles.splice(idx, 1);
			}
		}
	}

	pickSelected() {
		this.dialogRef.close(this.selectedFiles);
	}

	audit(fileId: string) {
		this.poemsService.getPoemsWithInternalImageId(fileId).subscribe({
			next: briefs => {
				if (briefs.length > 0) {
					const s = briefs.map(d => d.title).join('; ');
					this.alertService.info(s, false, $localize`Image actually in these poems`);
				} else {
					this.alertService.warn($localize`This image is orphaned.`);
				}

			},
			error: error => this.alertService.error(error)
		})
	}

	auditAll() {
		this.poemsService.getAssociatedPoemsOfAllImages().subscribe({
			next: dic => {
				let ec = 0;
				for (const p of this.pictures) {
					const ppm = dic[p.id!];
					if (ppm.length === 0) {
						p.count = 0;
						p.warning = 'Orphaned';
						ec++;
					} if (ppm.length !== p.count) {
						p.warning = ppm.map(d => d.title).join('; ');
						ec++
					}
				}

				if (ec) {
					this.alertService.warn($localize`A few places out of sync: ` + ec);
				} else {
					this.alertService.info($localize`Things look in sync.`);
				}
			},
			error: error => this.alertService.error(error)
		});
	}

	auditAndReconcile() {
		this.poemsService.auditAndReconcile().subscribe({
			next: count => {
				if (count > 0) {
					this.alertService.success($localize`Reconciled with changes: ${count}`, false);
					this.loadPictureBriefsWithCount();
				} else {
					this.alertService.info($localize`Things look fine.`);
				}
			},
			error: error => this.alertService.error(error)
		});

	}

	editMeta(a: Fonlow_PoemsApp_Data_Client.PictureMeta) {
		this.imgMetaDialogService.open({ id: a.id!, name: a.name!, description: a.description! }).subscribe(
			r => {
				if (r) {
					a.name = r.name;
					a.description = r.description;
					this.ref.detectChanges();
				}
			}
		)
	}

	transformSrcUrlToRelative(){
		this.confirmService.open($localize`Confirm`, 'The HTML tags may contain src tags pointing to local resources however with absolute URL. Transforming them to relative URL is good for the portability of the Web content. The action is irreversible. Do you want to proceed? ', 
			'Yes', 'No').subscribe(r=>{
				if (r){
					this.poemsService.refineImgLocalSrcUrlToRelativeAll().subscribe({
						next: c=>{
							this.alertService.info($localize`Total: ${c}`);
						},
						error: error => this.alertService.error(error)
					});
				}
			})
	}
}

@Injectable()
export class SettingsFilesDialogService {
	constructor(private dialog: MatDialog) { }

	open(data: { poemBriefs: Fonlow_PoemsApp_Data_Client.PoemBrief[], selectionMode: boolean, imgIds?: string[] | null }): Observable<PictureBriefEx[] | undefined> {
		const modalRef = this.dialog.open(SettingsFilesComponent, {
			disableClose: true,
			autoFocus: false,
			minWidth: '98vw',
			minHeight: '98vh',
			panelClass: 'dialog-full-content-height',
			data: data,
		});

		return modalRef.afterClosed();
	}

}
