import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { Title } from '@angular/platform-browser';
import { ActivatedRoute, Router } from '@angular/router';
import { AngularEditorModule } from '@kolkov/angular-editor';
import { AlertService, ConfirmService, WaitService } from 'nmce';
import { NmceHtmlEditorModule } from 'nmce-html-editor';
import { Fonlow_PoemsApp_Data_Client, PoemsApp_Controllers_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { LangSubjectService } from '../_services/types';
import { AppCache } from '../appCache';
import { NGMDModule } from '../ngmd.module';
import { AlbumMetaViewerComponent } from "../shared/albumMetaViewer.component";
import { AlbumsBase } from '../shared/albumsBase.directive';
import { AllMetaServiceModule } from '../shared/allMetaService.module';
import { BasicDataLoaderService } from '../shared/basicDataLoader.service';
import { MainButtonsComponent } from "../shared/main-buttons.component";
import { PoemViewerComponent } from "../shared/poemViewer.component";
import { AlbumHtmlEditorDialogService } from './albumHtmlEditor.component';
@Component({
    selector: 'albums-for-editor',
    templateUrl: './albums-for-editor.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [CommonModule, FormsModule, ReactiveFormsModule, NGMDModule, AngularEditorModule,
    NmceHtmlEditorModule, AllMetaServiceModule,
	AlbumMetaViewerComponent, PoemViewerComponent, MainButtonsComponent],
	providers: [BasicDataLoaderService, AlbumHtmlEditorDialogService,
	]
})
export class AlbumsForEditorComponent extends AlbumsBase {
	constructor( 
		protected router: Router,
		protected activatedRouter: ActivatedRoute,
		protected alertService: AlertService,
		protected albumsService: PoemsApp_Controllers_Client.Albums,
		protected poemsService: PoemsApp_Controllers_Client.Poems,
		protected basicDataLoaderService: BasicDataLoaderService,
		protected waitService: WaitService,
		protected langSubjectService: LangSubjectService,
		protected title: Title,
		protected ref: ChangeDetectorRef,
		private albumHtmlEditorDialogService: AlbumHtmlEditorDialogService,
		private confirmService: ConfirmService,
	) {
		super(router, activatedRouter, alertService, albumsService, poemsService, basicDataLoaderService, waitService, langSubjectService, title, ref);
	}

	editAlbum() {
		if (this.currentAlbum.id) {
			this.albumHtmlEditorDialogService.open(this.currentAlbum).subscribe(
				r => {
					if (r) {
						const index = this.albums.findIndex(d => d.id === r.id); //though I can use currentAlbumId;
						if (index >= 0) {
							this.albums[index] = r;
							this.currentAlbum = r;
						}
					}
				}
			);
		}
	}

	addAlbum() {
		const newAlbum: Fonlow_PoemsApp_Data_Client.Album = { bodyType: Fonlow_PoemsApp_Data_Client.BodyType.HTML };
		this.albumHtmlEditorDialogService.open(newAlbum).subscribe(
			r => {
				if (r) {
					AppCache.albumsDic[r.id!] = r;
					this.albums.unshift(r);
				}
			}
		);
	}

	deleteAlbum() {
		if (this.currentAlbum) {
			this.confirmService.open($localize`Deleting`, $localize`Are you sure to delete ${this.currentAlbum.title}?`).subscribe(
				yes => {
					if (yes) {
						this.albumsService.delete(this.currentAlbum!.id!).subscribe(
							{
								next: r => {
									if (r) {
										delete AppCache.albumsDic[this.currentAlbum!.id!];
										const idx = this.albums.findIndex(d => d.id === this.currentAlbum?.id);
										if (idx >= 0) {
											this.albums.splice(idx, 1);
										}

										this.currentAlbum = {};
										this.ref.detectChanges();
									}
								},
								error: error => this.alertService.error(error)
							}
						);
					}
				}
			);
		}
	}
}
