import { Component, OnDestroy } from '@angular/core';
import { Router } from '@angular/router';
import { Subject } from 'rxjs';

import { AlertService, ConfirmService } from 'nmce';
import { takeUntil } from 'rxjs/operators';

import {Fonlow_AspNetCore_Identity_Client, Fonlow_Auth_Controllers_Client} from '../../clientapi/WebApiNG2ClientAuto';
import { UserDialogService } from './user.component';
import { CommonModule } from '@angular/common';
import { NGMDModule } from '../ngmd.module';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';

/**
 * Users search and list
 */
@Component({
    selector: 'account-users',
    templateUrl: 'users.component.html',
    standalone: true,
	imports: [
		CommonModule,
		FormsModule,
		ReactiveFormsModule,
		NGMDModule,	
	],
	providers: [UserDialogService]
})
export class UsersComponent implements OnDestroy {
	loading = false;
	submitted?: boolean;
	model: Fonlow_AspNetCore_Identity_Client.UserSearchModel = {};
	users: Fonlow_AspNetCore_Identity_Client.UserItem[] = []; //store the search result.
	hasUsers = false;
	private unsubscribe: Subject<void> = new Subject();

	constructor(
		private service: Fonlow_Auth_Controllers_Client.Account,
		private alertService: AlertService,
		private router: Router,
		private confirmService: ConfirmService,
		private userDialogService: UserDialogService,
	) {
	}

	private alive = true;

	ngOnDestroy(): void {
		console.debug('UsersComponent destroyed');
		this.alive = false;
	}

	search() {
		this.loading = true;
		this.service.search(this.model).pipe(takeUntil(this.unsubscribe)).subscribe({
			next: data => {
				this.users = data;
				this.alertService.success($localize`Search successful returning ${data.length}.`);
				this.loading = false;
				this.submitted = true;
				this.hasUsers = this.users.length > 0;
			},
			error: error => {
				this.alertService.error(error);
				this.loading = false;
				this.hasUsers = false;
			}
		}
		);
	}

	clear() {
		this.model.keyword = undefined;
		this.model.dateBegin = undefined;
		this.model.dateEnd = undefined;
		this.submitted = false;
	}

	/**
	 * Delete user. And the HTML will refresh by NG2 runtime.
	 * @param u
	 */
	delete(u: Fonlow_AspNetCore_Identity_Client.UserItem) {
		this.confirmService.open($localize`Confirm`, $localize`Are you sure to delete?`).pipe(takeUntil(this.unsubscribe)).subscribe(
			data => {
				if (data) {
					this.service.removeUser(u.id)
						.subscribe(
							response => {
								//remove from the array, and NG2 will do the dirty work of removing the element.
								const index = this.users.indexOf(u, 0);
								if (index > -1) {
									this.users.splice(index, 1);
								}

								this.alertService.success($localize`Deleted`);
							},
							error => {
								this.alertService.error(error);
							}
						);
				}
			});
	}

	/**
	 * Edit the user through routing to UserComponent.
	 * @param u
	 */
	update(u: Fonlow_AspNetCore_Identity_Client.UserItem) {
		this.userDialogService.open(u.id).subscribe();
	}

	updateDateBegin(date: Date) {
		this.model.dateBegin = date;
	}

	updateDateEnd(date: Date) {
		this.model.dateEnd = date;
	}

}
