import { ChangeDetectionStrategy, Component, Injectable, OnInit } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { Observable } from 'rxjs';
import { APP_DI_CONFIG } from '../app-config';
import { NGMDModule } from '../ngmd.module';
import { ViewSettingsComponent } from "../shared/view-settings.component";
import { SettingsAuthorComponent } from './settings-author.component';
import { SettingsEditComponent } from './settings-edit.component';
import { SettingsPoetryComponent } from './settings-poetry.component';


@Component({
    selector: 'settings-index',
    templateUrl: 'settings-index.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [NGMDModule,
    SettingsAuthorComponent,
    SettingsPoetryComponent,
    SettingsEditComponent, ViewSettingsComponent]
})
export class SettingsIndexComponent implements OnInit {
	get isSmallScreen() {
		return APP_DI_CONFIG.isSmallScreen;
	}

	constructor(
	) {
		console.debug('SettingsIndexComponent created');
	}
	ngOnInit(): void {
	}

	close() {

	}

}

@Injectable()
export class SettingsDialogService {
	constructor(private dialog: MatDialog) { }

	/**
	 * Display poem object in editor.
	 * @param data
	 */
	open(): Observable<void> {
		const modalRef = this.dialog.open(SettingsIndexComponent, {
			disableClose: true,
			autoFocus: false,
			minWidth: '98vw',
			minHeight: '98vh',
			panelClass: 'dialog-full-content-height',
		});

		return modalRef.afterClosed();
	}

}
