import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, OnInit } from '@angular/core';
import { FormBuilder, FormControl, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { AngularEditorModule } from '@kolkov/angular-editor';
import { AlertService } from 'nmce';
import { NmceHtmlEditorModule } from 'nmce-html-editor';
import { PoemsApp_Controllers_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { APP_DI_CONFIG, mySettingsList } from '../app-config';
import { NGMDModule } from '../ngmd.module';

@Component({
    selector: 'settings-edit',
    templateUrl: 'settings-edit.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [		CommonModule, FormsModule, ReactiveFormsModule,  NGMDModule, AngularEditorModule,
		NmceHtmlEditorModule,
		]
})
export class SettingsEditComponent implements OnInit {
	usePublishedControl = new FormControl(true);
	useRyhmesControl = new FormControl(true);
	useNumberOfStanzaControl = new FormControl(true);
	useFirstPublishUrlControl = new FormControl(true);
	useAnnotationsControl = new FormControl(true);
	useNumberedAnnotationsControl = new FormControl(true);
	useTagsControl = new FormControl(true);
	useAlbumsControl = new FormControl(true);
	useYearFirstInPublishedControl = new FormControl(false);
	advancedClipboardEnabledControl = new FormControl(false);

	totalCountOfStanza = 0;

	constructor(private router: Router,
		private keyValuesService: PoemsApp_Controllers_Client.KeyValues,
		private poemsService: PoemsApp_Controllers_Client.Poems,
		private alertService: AlertService,
		private fb: FormBuilder,
		private ref: ChangeDetectorRef,
	) {
		this.usePublishedControl.valueChanges.subscribe(
			d => {
				APP_DI_CONFIG.usePublished = d!;
				this.saveSetting('settings.usePublished', this.usePublishedControl);
			}
		);

		this.useRyhmesControl.valueChanges.subscribe(
			d => {
				APP_DI_CONFIG.useRyhmes = d!;
				this.saveSetting('settings.useRyhmes', this.useRyhmesControl);
			}
		);

		this.useNumberOfStanzaControl.valueChanges.subscribe(
			d => {
				APP_DI_CONFIG.useNumberOfStanza = d!;
				this.saveSetting('settings.useNumberOfStanza', this.useNumberOfStanzaControl);
			}
		);

		this.useFirstPublishUrlControl.valueChanges.subscribe(
			d => {
				APP_DI_CONFIG.useFirstPublishUrl = d!;
				this.saveSetting('settings.useFirstPublishUrl', this.useFirstPublishUrlControl);
			}
		);

		this.useAnnotationsControl.valueChanges.subscribe(
			d => {
				APP_DI_CONFIG.useAnnotations = d!;
				this.saveSetting('settings.useAnnotations', this.useAnnotationsControl);
			}
		);

		this.useNumberedAnnotationsControl.valueChanges.subscribe(
			d => {
				APP_DI_CONFIG.useNumberedAnnotations = d!;
				this.saveSetting('settings.useNumberedAnnotations', this.useNumberedAnnotationsControl);
			}
		);

		this.useTagsControl.valueChanges.subscribe(
			d => {
				APP_DI_CONFIG.useTags = d!;
				this.saveSetting('settings.useTags', this.useTagsControl);
			}
		);

		this.useAlbumsControl.valueChanges.subscribe(
			d => {
				APP_DI_CONFIG.useAlbums = d!;
				this.saveSetting('settings.useAlbums', this.useAlbumsControl);
			}
		);

		this.useYearFirstInPublishedControl.valueChanges.subscribe(
			d => {
				APP_DI_CONFIG.useYearFirstInPublished = d!;
				this.saveSetting('settings.useYearFirstInPublished', this.useYearFirstInPublishedControl);
			}
		);

		this.advancedClipboardEnabledControl.valueChanges.subscribe(
			d => {
				APP_DI_CONFIG.advancedClipboardEnabled = d!;
				this.saveSetting('settings.advancedClipboardEnabled', this.advancedClipboardEnabledControl);
			}
		);

	}

	ngOnInit(): void {
		console.debug('current route: ' + this.router.url);
		this.keyValuesService.getValues(mySettingsList).subscribe({
			next: ss => {
				this.usePublishedControl.setValue(ss['settings.usePublished'] != 'false', { emitEvent: false });
				this.useRyhmesControl.setValue(ss['settings.useRyhmes'] != 'false', { emitEvent: false });
				this.useNumberOfStanzaControl.setValue(ss['settings.useNumberOfStanza'] != 'false', { emitEvent: false });
				this.useFirstPublishUrlControl.setValue(ss['settings.useFirstPublishUrl'] != 'false', { emitEvent: false });
				this.useAnnotationsControl.setValue(ss['settings.useAnnotations'] != 'false', { emitEvent: false });
				this.useNumberedAnnotationsControl.setValue(ss['settings.useNumberedAnnotations'] != 'false', { emitEvent: false });
				this.useTagsControl.setValue(ss['settings.useTags'] != 'false', { emitEvent: false });
				this.useAlbumsControl.setValue(ss['settings.useAlbums'] != 'false', { emitEvent: false });
				this.useYearFirstInPublishedControl.setValue(ss['settings.useYearFirstInPublished'] == 'true', { emitEvent: false });
				this.advancedClipboardEnabledControl.setValue(ss['settings.advancedClipboardEnabled'] == 'true', { emitEvent: false });
			},
			error: error => this.alertService.error(error)
		}
		);

		this.poemsService.getTotalCountOfStanza().subscribe(
			{
				next: c => {
					this.totalCountOfStanza = c;
					this.ref.detectChanges();
				},
				error: error => this.alertService.error(error)
			}
		)
	}

	get defaultActive(): boolean {
		return this.router.url === '/settings';
	}

	saveSetting(key: string, control: FormControl) {
		this.keyValuesService.upsertKey(key, control.value.toString()).subscribe({
			next: d => {
				control.markAsPristine();
				this.alertService.success($localize`Saved`);
			},
			error: error => this.alertService.error(error)
		}
		)
	}
}
