import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, Injectable, OnInit } from '@angular/core';
import { MatDialog, MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
import { AlertService } from 'nmce';
import { Observable } from 'rxjs';
import { Fonlow_PoemsApp_Data_Client, PoemsApp_Controllers_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { EditPoemSubjectService, PictureBriefEx } from '../_services/types';
import { NGMDModule } from '../ngmd.module';
import { NotLocalImageComponent } from './not-local-image.component';
import { ReactiveFormsModule } from '@angular/forms';

@Component({
    selector: 'settings-not-local-images',
    templateUrl: 'settings-not-local-images.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [NGMDModule, ReactiveFormsModule, NotLocalImageComponent]
})
export class SettingsNotLocalImagesComponent implements OnInit {
	pictureURLs: string[] = [];
	urlToPicturesDic: { [id: string]: Array<string> } = {};
	picturesDic: { [id: string]: Fonlow_PoemsApp_Data_Client.Picture } = {};

	poemBriefsDic: { [id: string]: Fonlow_PoemsApp_Data_Client.PoemBrief };

	orphansExist = false;

	selectedFiles: PictureBriefEx[] = [];

	constructor(
		@Inject(MAT_DIALOG_DATA) public data: { poemBriefs: Fonlow_PoemsApp_Data_Client.PoemBrief[], selectionMode: boolean },
		private dialogRef: MatDialogRef<SettingsNotLocalImagesComponent>,
		private poemsService: PoemsApp_Controllers_Client.Poems,
		private picturesService: PoemsApp_Controllers_Client.Files,
		private alertService: AlertService,
		private editPoemSubjectService: EditPoemSubjectService,
		private ref: ChangeDetectorRef,
	) {
		this.poemBriefsDic = Object.assign({}, ...data.poemBriefs.map((x) => ({ [x.id!]: x }))); // array to dic
	}

	ngOnInit(): void {
		this.loadPictureBriefsWithCount();
	}

	private loadPictureBriefsWithCount() {
		this.poemsService.getAllNotLocalImagesOfPoems().subscribe(
			{
				next: data => {
					this.urlToPicturesDic = data;
					this.pictureURLs = Object.keys(data);
					this.ref.detectChanges();
				},
				error: error => this.alertService.error(error)
			}
		);
	}

	editPoem(poemId: string) {
		this.editPoemSubjectService.emit(poemId);
	}

	pickOrUnpick(toPick: boolean, pic: PictureBriefEx) {
		const idx = this.selectedFiles.findIndex(d => d.id === pic.id);
		if (toPick) {
			if (idx < 0) {
				this.selectedFiles.push(pic);
			}
		} else {
			if (idx >= 0) {
				this.selectedFiles.splice(idx, 1);
			}
		}
	}

	pickSelected() {
		this.dialogRef.close(this.selectedFiles);
	}

	makeLocalImage(srcUrl: string) {
		const poemIds = this.urlToPicturesDic[srcUrl];
		this.picturesService.downloadRemoteToLocal({
			poemIds: poemIds,
			srcUrl: srcUrl,
			description: 'temp desc',
			name: 'funkytemp'
		}).subscribe({
			next: pm => {
				if (pm) {
					this.alertService.success($localize`Done`);
				} else {
					this.alertService.warn('Something very wrong');
				}
			},
			error: error => this.alertService.error(error)
		})
	}

	removeImageCard(srcUrl: string) {
		const idx = this.pictureURLs.indexOf(srcUrl);
		if (idx >= 0) {
			this.pictureURLs.splice(idx, 1);
		}
	}
}

@Injectable()
export class SettingsNotLocalImagesDialogService {
	constructor(private dialog: MatDialog) { }

	open(data: { poemBriefs: Fonlow_PoemsApp_Data_Client.PoemBrief[], selectionMode: boolean }): Observable<PictureBriefEx[] | undefined> {
		const modalRef = this.dialog.open(SettingsNotLocalImagesComponent, {
			disableClose: true,
			autoFocus: false,
			minWidth: '98vw',
			minHeight: '98vh',
			panelClass: 'dialog-full-content-height',
			data: data,
		});

		return modalRef.afterClosed();
	}

}
