import { COMMA, ENTER } from '@angular/cdk/keycodes';
import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, ElementRef, EventEmitter, Inject, Injectable, Input, OnInit, Output, ViewChild } from '@angular/core';
import { FormGroup, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialog, MatDialogRef } from '@angular/material/dialog';
import { AngularEditorComponent, AngularEditorConfig, AngularEditorModule } from '@kolkov/angular-editor';
import { AlertService } from 'nmce';
import { NmceHtmlEditorModule } from 'nmce-html-editor';
import { Observable } from 'rxjs';
import { Fonlow_PoemsApp_Data_Client, PoemsApp_Controllers_Client } from 'src/clientapi/WebApiNG2ClientAuto';
import { APP_DI_CONFIG } from '../app-config';
import { AppCache } from '../appCache';
import { NGMDModule } from '../ngmd.module';

import { HtmlEditorMenuComponent } from './htmlEditorMenu.component';

@Component({
    selector: 'annotation-html-editor',
    templateUrl: './annotationHtmlEditor.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [		CommonModule, FormsModule, ReactiveFormsModule,  NGMDModule, AngularEditorModule,
		NmceHtmlEditorModule,
	HtmlEditorMenuComponent,
]
})
export class AnnotationHtmlEditorComponent implements OnInit {
	get note() {
		if (!this.noteControl) {
			return '';
		}

		return this.noteControl.value;
	}

	//private _noteControl: FormControl = new FormControl();
	//get noteControl(): FormControl {
	//	return this._noteControl;
	//}
	//set noteControl(v: FormControl) {
	//	this._noteControl = v;
	//}
	get noteControl() {
		return this.annotationForm.controls.description;
	}

	get modified(): boolean {
		return this.annotationForm.dirty;
	}

	private viewPortHeight = Math.max(document.documentElement.clientHeight, window.innerHeight || 0);
	maxRows = (this.viewPortHeight * .90 - 150) / 16;

	/**
	 * Friendly name
	 */
	@Input()
	noteLabel: string;

	@Output()
	modelChanged: EventEmitter<string> = new EventEmitter<string>();

	@ViewChild('htmlEditor') htmlEditor?: AngularEditorComponent;

	@ViewChild('annotationFormSection') annotationFormSection?: ElementRef;

	readonly = false;

	//private viewPortHeight = Math.max(document.documentElement.clientHeight, window.innerHeight || 0);

	config: AngularEditorConfig;

	annotationForm: FormGroup<Fonlow_PoemsApp_Data_Client.AnnotationFormProperties>;

	addOnBlur = true;
	readonly separatorKeysCodes = [ENTER, COMMA] as const;
	constructor(
		@Inject(MAT_DIALOG_DATA) public annotation: Fonlow_PoemsApp_Data_Client.Annotation,
		public dialogRef: MatDialogRef<AnnotationHtmlEditorComponent>,
		private alertService: AlertService,
		private annotationsService: PoemsApp_Controllers_Client.Annotations,
		private ref: ChangeDetectorRef,
	) {
		this.config = APP_DI_CONFIG.angularEditorConfig;
		if (APP_DI_CONFIG.isChinese) {
			this.config.spellcheck = false;
		}

		this.annotationForm = Fonlow_PoemsApp_Data_Client.CreateAnnotationFormGroup();
		this.annotationForm.patchValue(this.annotation);
		this.noteLabel = this.annotation.id ? $localize`Edit` : $localize`Add`;
	}

	/**
	 * For existing, load; for new, if with letterTemplateId, then use the template to render the data and show html generated;
	 * otherwise, show blank HTML doc.
	 */
	ngOnInit(): void {
	}

	ngAfterViewInit() {
		if (this.annotationFormSection && APP_DI_CONFIG.defaultWrittenLanguage) {
			this.annotationFormSection.nativeElement.lang = APP_DI_CONFIG.defaultWrittenLanguage;
		}
	}

	save() {
		const raw = this.annotationForm.getRawValue() as Fonlow_PoemsApp_Data_Client.Annotation;
		if (this.annotation.id) {
			this.annotationsService.update(raw).subscribe(
				{
					next: r => {
						this.alertService.success($localize`Updated`, true);
						this.dialogRef.close(raw);
					},
					error: error => this.alertService.error(error)
				}
			)
		} else {
			if (raw.name) {
				const annotationNameExists = AppCache.annotations.findIndex(d => d.name == this.annotationForm.controls.name.value) >= 0;
				if (annotationNameExists) {
					this.alertService.warn($localize`Annotation with the same name exists.`);
				} else {
					this.annotationsService.add(raw).subscribe(
						{
							next: newAnnotation => {
								this.alertService.success($localize`Added`, true);
								this.dialogRef.close(newAnnotation);
							},
							error: error => this.alertService.error(error)
						}
					);
				}
			} else {
				this.alertService.warn($localize`Please give the annotation a name`);
			}
		}
	}

	reset() {
		if (this.annotation.id) {
			this.annotationsService.get(this.annotation.id, APP_DI_CONFIG.convertZhHandler).subscribe(
				{
					next: r => {
						if (r) {
							this.annotation = r;
							this.annotationForm.reset(undefined);
							this.annotationForm.patchValue(r); // this.noteControl is included inside
							this.ref.detectChanges();
						} else {
							this.alertService.warn($localize`Not found`);
						}
					},
					error: error => this.alertService.error(error)
				}
			)
		} else {
			this.annotation = {};
			this.annotationForm.reset(undefined);
			this.annotationForm.patchValue(this.annotation);
		}
	}

	close() {
		this.dialogRef.close(undefined);
	}

	//print() {
	//	if (!this.noteControl.value) {
	//		this.alertService.warn('Not allow to print empty document.');
	//		return;
	//	}

	//	HtmlPrintFunc.print(this.noteControl.value);
	//}

}

@Injectable()
export class AnnotationHtmlEditorDialogService {
	constructor(private dialog: MatDialog) { }

	/**
	 * Display HTML document or create new HTML document with a template
	 * @param data
	 */
	open(data: Fonlow_PoemsApp_Data_Client.Annotation): Observable<Fonlow_PoemsApp_Data_Client.Annotation> {
		const modalRef = this.dialog.open(AnnotationHtmlEditorComponent, {
			disableClose: true,
			autoFocus: false,
			minWidth: '98vw',
			minHeight: '98vh',
			panelClass: 'dialog-full-content-height',
			data: data,
		});

		return modalRef.afterClosed();
	}

}

