import { COMMA, ENTER } from '@angular/cdk/keycodes';
import { CommonModule } from '@angular/common';
import { AfterViewInit, ChangeDetectionStrategy, Component, ElementRef, EventEmitter, Inject, Injectable, Input, OnInit, Output, ViewChild } from '@angular/core';
import { FormGroup, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialog, MatDialogRef } from '@angular/material/dialog';
import { AngularEditorComponent, AngularEditorConfig, AngularEditorModule } from '@kolkov/angular-editor';
import { AlertService } from 'nmce';
import { NmceHtmlEditorModule } from 'nmce-html-editor';
import { Observable } from 'rxjs';
import { Fonlow_PoemsApp_Data_Client, PoemsApp_Controllers_Client } from 'src/clientapi/WebApiNG2ClientAuto';
import { APP_DI_CONFIG } from '../app-config';
import { NGMDModule } from '../ngmd.module';

import { HtmlEditorMenuComponent } from './htmlEditorMenu.component';
@Component({
    selector: 'numberedAnnotation-html-editor',
    templateUrl: './numberedAnnotationHtmlEditor.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [
		CommonModule, FormsModule, ReactiveFormsModule,  NGMDModule, AngularEditorModule,
		NmceHtmlEditorModule,
		
		HtmlEditorMenuComponent,
	]
})
export class NumberedAnnotationHtmlEditorComponent implements OnInit, AfterViewInit {
	get note() {
		if (!this.noteControl) {
			return '';
		}

		return this.noteControl.value;
	}

	//private _noteControl: FormControl = new FormControl();
	//get noteControl(): FormControl {
	//	return this._noteControl;
	//}
	//set noteControl(v: FormControl) {
	//	this._noteControl = v;
	//}

	get noteControl() {
		return this.numberedAnnotationForm.controls.description;
	}

	get modified(): boolean {
		return this.numberedAnnotationForm.dirty;
	}

	private viewPortHeight = Math.max(document.documentElement.clientHeight, window.innerHeight || 0);
	maxRows = (this.viewPortHeight * .90 - 150) / 16;

	/**
	 * Friendly name
	 */
	@Input()
	noteLabel: string;

	@Output()
	modelChanged: EventEmitter<string> = new EventEmitter<string>();

	readonly = false;

	//private viewPortHeight = Math.max(document.documentElement.clientHeight, window.innerHeight || 0);

	config: AngularEditorConfig;

	@ViewChild('htmlEditor') htmlEditor?: AngularEditorComponent;

	@ViewChild('numberedAnnotationFormSection') numberedAnnotationFormSection?: ElementRef;

	numberedAnnotationForm: FormGroup<Fonlow_PoemsApp_Data_Client.NumberedAnnotationFormProperties>;

	addOnBlur = true;
	readonly separatorKeysCodes = [ENTER, COMMA] as const;
	constructor(
		@Inject(MAT_DIALOG_DATA) public numberedAnnotation: Fonlow_PoemsApp_Data_Client.NumberedAnnotation,
		public dialogRef: MatDialogRef<NumberedAnnotationHtmlEditorComponent>,
		private alertService: AlertService,
		private numberedAnnotationsService: PoemsApp_Controllers_Client.NumberedAnnotations,
	) {
		this.config = APP_DI_CONFIG.angularEditorConfig;
		if (APP_DI_CONFIG.isChinese) {
			this.config.spellcheck = false;
		}

		this.numberedAnnotationForm = Fonlow_PoemsApp_Data_Client.CreateNumberedAnnotationFormGroup();
		this.numberedAnnotationForm.patchValue(this.numberedAnnotation);
		this.noteLabel = $localize`Edit ` + this.numberedAnnotation.orderNumber;
	}

	//private createNumberedAnnotationForm() {
	//	return this.fb.group(
	//		{
	//			id: [undefined],
	//			poemId: [undefined],
	//			orderNumber: [undefined],
	//			description: this.noteControl,
	//			url: [undefined],
	//		}
	//	);
	//}

	/**
	 * For existing, load; for new, if with letterTemplateId, then use the template to render the data and show html generated;
	 * otherwise, show blank HTML doc.
	 */
	ngOnInit(): void {
	}

	ngAfterViewInit() {
		if (this.numberedAnnotationFormSection && APP_DI_CONFIG.defaultWrittenLanguage) {
			this.numberedAnnotationFormSection.nativeElement.lang = APP_DI_CONFIG.defaultWrittenLanguage;
		}
	}

	save() {
		const raw = this.numberedAnnotationForm.getRawValue() as Fonlow_PoemsApp_Data_Client.NumberedAnnotation;
		if (this.numberedAnnotation.id) {
			this.numberedAnnotationsService.update(raw).subscribe(
				{
					next: r => {
						this.alertService.success($localize`Updated`, true);
						this.dialogRef.close(raw);
					},
					error: error => this.alertService.error(error)
				}
			)
		}
	}

	reset() {
		if (this.numberedAnnotation.id) {
			this.numberedAnnotationsService.get(this.numberedAnnotation.id, APP_DI_CONFIG.convertZhHandler).subscribe(
				{
					next: r => {
						if (r) {
							this.numberedAnnotation = r;
							this.numberedAnnotationForm.reset(undefined);
							this.numberedAnnotationForm.patchValue(r); // this.noteControl is included inside
						} else {
							this.alertService.warn($localize`Not found`);
						}
					},
					error: error => this.alertService.error(error)
				}
			)
		}
	}

	close() {
		this.dialogRef.close(undefined);
	}

	//print() {
	//	if (!this.noteControl.value) {
	//		this.alertService.warn('Not allow to print empty document.');
	//		return;
	//	}

	//	HtmlPrintFunc.print(this.noteControl.value);
	//}

}

@Injectable()
export class NumberedAnnotationHtmlEditorDialogService {
	constructor(private dialog: MatDialog) { }

	/**
	 * Display HTML document or create new HTML document with a template
	 * @param data
	 */
	open(data: Fonlow_PoemsApp_Data_Client.NumberedAnnotation): Observable<Fonlow_PoemsApp_Data_Client.NumberedAnnotation> {
		const modalRef = this.dialog.open(NumberedAnnotationHtmlEditorComponent, {
			disableClose: true,
			autoFocus: false,
			minWidth: '98vw',
			minHeight: '98vh',
			panelClass: 'dialog-full-content-height',
			data: data,
		});

		return modalRef.afterClosed();
	}

}

