import { Component, OnInit, Input, Inject } from '@angular/core';

import { MatCheckboxChange } from '@angular/material/checkbox';
import { AlertService, NmceComponentsModule } from 'nmce';


import { AccountHelper } from './functions';

import { Fonlow_AspNetCore_Identity_Client, Fonlow_Auth_Controllers_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { CommonModule } from '@angular/common';
import { NGMDModule } from '../ngmd.module';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';

/**
 * Role checkboxes to assign a role to an existing user
 */
@Component({
    selector: 'account-roles',
    templateUrl: 'roles.component.html',
    standalone: true,
	imports: [
		CommonModule,
		FormsModule,
		ReactiveFormsModule,
		NGMDModule,	
	],
})
export class RolesComponent implements OnInit {
	allRoleNames: Array<string> = [];

	/**
	 * Roles of an existing user. This could be provided by a parent component like UserComponent.
	 */
	@Input() roles?: Array<string> | null = [];

	/**
	 * user ID of an existing user. This could be provided by a parent component like RegisterComponent.
	 */
	@Input() userId?: string;

	constructor(private service: Fonlow_Auth_Controllers_Client.Account, private alertService: AlertService) {

	}

	ngOnInit(): void {
		if (!this.allRoleNames || this.allRoleNames.length === 0) {
			this.service.getAllRoleNames().subscribe(
				{
					next: items => {
						this.allRoleNames = items;
					},
					error: error => this.alertService.error(error)
				}
			);
		}

		if (this.userId) {
			this.service.getRoles(this.userId).subscribe(
				{
					next: items => this.roles = items,
					error: error => this.alertService.error(error)
				}
			);
		}
	}

	/**
	 * For the [checked] attribute in html, so to initially display a checkbox checked or not.
	 * @param roleName
	 */
	shouldChecked(roleName: string): boolean {
		if (!this.roles || this.roles.length === 0) {
			return false;
		}

		return this.roles.findIndex(x=>x.toUpperCase()==roleName) > -1;
	}

	/**
	 * For the (change) event in html, so to add or remove role.
	 * @param event
	 */
	addOrRemoveRole(event: MatCheckboxChange) {
		if (!this.userId) {
			this.alertService.error('Ask programmer to fix this.');
			return;
		}

		const roleName = event.source.id;
		if (roleName === 'Admin' && !AccountHelper.isAdmin()) {
			event.source.checked = !event.source.checked;
			this.alertService.warn($localize`Only admin can assign or unassign admin.`);
			return;
		}

		if (event.checked) {
			this.service.addRole(this.userId, roleName).subscribe(
				{
					next: () => {
						this.alertService.success($localize`Role ${roleName} added.`);
					},
					error: (error) => {
						event.checked = false;
						this.alertService.error(error);
					}
				}
			);
		} else {
			this.service.removeRole(this.userId, roleName).subscribe(
				{
					next: () => {
						this.alertService.success($localize`Role ${roleName} removed.`);
					},
					error: (error) => {
						event.checked = true;
						this.alertService.error(error);
					}
				}
			);
		}
	}



}
