import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, Component, Inject, ViewChild } from '@angular/core';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialog, MatDialogRef } from '@angular/material/dialog';
import { MatSelectionList, MatSelectionListChange } from '@angular/material/list';
import { AngularEditorModule } from '@kolkov/angular-editor';
import { NmceHtmlEditorModule } from 'nmce-html-editor';
import { Observable } from 'rxjs';
import { APP_DI_CONFIG } from '../app-config';
import { NGMDModule } from '../ngmd.module';

/**
 * Display a list of items to select one.
 * This will be shown by a concrete service of ItemListDialogServiceBase<T>.
 */
@Component({
    templateUrl: './itemsSelectionDialog.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [		CommonModule, FormsModule, ReactiveFormsModule,  NGMDModule, AngularEditorModule,
		NmceHtmlEditorModule,
		]
})
export class ItemsSelectionDialogComponent {
	title: string;

	/**
	 * Must be an array type
	 */
	items: any;

	/*
	 * Point to the actual implementation in the concrete class of ItemListDialogServiceBase<T>.
	 * Item type must be the base type of the array type.
	 */
	toString: (item: any) => string;

	@ViewChild('itemsSelection') itemsSelection?: MatSelectionList;

	get anySelected() {
		return this.itemsSelection?.selectedOptions?.selected?.length;
	}

	get actionsAlign() {
		return APP_DI_CONFIG.DialogActionsAlign;
	}

	/**
	 *
	 * @param data data.items type should be array. data.toStringCallback is to conver an item in the array into string for displaying.
	 * @param dialogRef
	 */
	constructor(@Inject(MAT_DIALOG_DATA) public data: { title: string, items: any, multiple: boolean, toStringCallback: (item: any) => string }, private dialogRef: MatDialogRef<ItemsSelectionDialogComponent>,
	) {
		this.title = data.title;
		this.items = data.items;
		this.toString = data.toStringCallback;
	}

	cancel(): void {
		this.dialogRef.close();
	}

	confirm(): void {
		this.dialogRef.close(this.itemsSelection!.selectedOptions.selected.map(o => o.value));
	}

	itemSelectionChange(e: MatSelectionListChange) {
		if (this.data.multiple) {
			if (this.items.length === this.itemsSelection!.selectedOptions.selected.length) {
				this.confirm();
			}
		} else {
			this.dialogRef.close(e.source.selectedOptions.selected[0]?.value);
		}
	}

	confirmAll() {
		this.itemsSelection?.selectAll();
		this.confirm();
	}
}

/**
 * Show a list of object items and select one. T could be a string type, or any object type that could be presented as a literal description.
 */
export abstract class ItemsSelectionDialogServiceBase<T> {
	constructor(protected dialog: MatDialog) { }

	/**
	 * Display a list of options. With OptionsComponent, it will be a list of buttons labeled by the option texts.
	 * @param title
	 * @param items
	 * @returns object item selected.
	 */
	open(title: string, items: { [k: string]: T }[] | T[]): Observable<T[]> {
		const modalRef = this.dialog.open(ItemsSelectionDialogComponent, { disableClose: true, autoFocus: false, data: { title: title, items: items, multiple: true, toStringCallback: this.toString } });
		return modalRef.afterClosed();
	}

	openForSingle(title: string, items: { [k: string]: T }[] | T[]): Observable<T | null> {
		const modalRef = this.dialog.open(ItemsSelectionDialogComponent, { disableClose: true, autoFocus: false, data: { title: title, items: items, multiple: false, toStringCallback: this.toString } });
		return modalRef.afterClosed();
	}

	/**
	 * Translate item into a string printed in the dialog.
	 * @param item
	 */
	abstract toString(item: { [k: string]: T } | T): string;

}

