import { Fonlow_AspNetCore_Identity_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { APP_STATUSES } from '../app-statuses';

export class AccountHelper {
	public static isAdminOrManager(): boolean {
		const currentUser = AccountHelper.getValidUser();
		if (currentUser && currentUser.roles) {
			return currentUser.roles.indexOf('Admin') >= 0 || currentUser.roles.indexOf('Manager') >= 0;
		}

		return false;
	}

	public static isAdmin(): boolean {
		const currentUser = AccountHelper.getValidUser();
		if (currentUser && currentUser.roles) {
			return currentUser.roles.indexOf('Admin') >= 0;
		}

		return false;
	}

	static getValidUser(): Fonlow_AspNetCore_Identity_Client.UserInfoViewModel | undefined {
		return APP_STATUSES.userInfo;
	}

	public static canHandleAppointments(): boolean {
		const currentUser = AccountHelper.getValidUser();
		if (currentUser && currentUser.roles) {
			return currentUser.roles.indexOf('Admin') >= 0 || currentUser.roles.indexOf('Manager') >= 0 || currentUser.roles.indexOf('Finance') >= 0 || currentUser.roles.indexOf('Doctor') >= 0 || currentUser.roles.indexOf('Admin') >= 0;
		}

		return false;
	}

	public static isDoctor(): boolean {
		const currentUser = AccountHelper.getValidUser();
		if (currentUser && currentUser.roles) {
			return currentUser.roles.indexOf('Doctor') >= 0;
		}

		return false;
	}

	public static isPatientOnly(): boolean {
		const currentUser = AccountHelper.getValidUser();
		if (currentUser && currentUser.roles) {
			return currentUser.roles.length === 1 && currentUser.roles.indexOf('Patient') >= 0;
		}

		return false;
	}


}
