import { CommonModule } from '@angular/common';
import { AfterViewInit, ChangeDetectionStrategy, ChangeDetectorRef, Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { FormControl, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { AngularEditorModule } from '@kolkov/angular-editor';
import { AlertService } from 'nmce';
import { NmceHtmlEditorModule } from 'nmce-html-editor';
import { PoemsApp_Controllers_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { APP_DI_CONFIG } from '../app-config';
import { NGMDModule } from '../ngmd.module';

@Component({
    selector: 'settings-author',
    templateUrl: 'settings-author.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [		CommonModule, FormsModule, ReactiveFormsModule,  NGMDModule, AngularEditorModule,
		NmceHtmlEditorModule,
		]
})
export class SettingsAuthorComponent implements OnInit, AfterViewInit {
	authorNameControl = new FormControl();
	pennameControl = new FormControl();
	bioControl = new FormControl();
	@ViewChild('authorSection') authorSection?: ElementRef;

	get defaultActive(): boolean {
		return this.router.url === '/settings';
	}

	constructor(private router: Router,
		private keyValuesService: PoemsApp_Controllers_Client.KeyValues,
		private alertService: AlertService,
		private ref: ChangeDetectorRef,
	) {

	}

	ngOnInit(): void {
		console.debug('current route: ' + this.router.url);
		this.keyValuesService.getValues(['settings.authorName', 'settings.penname', 'settings.bio']).subscribe({
			next: ss => {
				this.authorNameControl.setValue(ss['settings.authorName']);
				this.pennameControl.setValue(ss['settings.penname']);
				this.bioControl.setValue(ss['settings.bio']);
				this.ref.detectChanges();
			},
			error: error => this.alertService.error(error)
		}
		);
	}

	ngAfterViewInit() {
		if (this.authorSection && APP_DI_CONFIG.defaultWrittenLanguage) {
			this.authorSection.nativeElement.lang = APP_DI_CONFIG.defaultWrittenLanguage;
			this.ref.detectChanges();
		}
	}

	saveSetting(key: string, control: FormControl) {
		this.keyValuesService.upsertKey(key, control.value).subscribe({
			next: d => {
				control.markAsPristine();
				this.ref.detectChanges();
				this.alertService.success($localize`Saved`);
			},
			error: error => this.alertService.error(error)
		}
		)
	}

}
