import { ChangeDetectionStrategy, ChangeDetectorRef, Component, OnInit } from '@angular/core';
import { FormArray, FormBuilder, FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { AlertService, ConfirmService } from 'nmce';
import { Fonlow_PoemsApp_Data_Client, PoemsApp_Controllers_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { NGMDModule } from '../ngmd.module';

@Component({
    selector: 'settings-poetry',
    templateUrl: 'settings-poetry.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [NGMDModule, ReactiveFormsModule]
})
export class SettingsPoetryComponent implements OnInit {
	writtenLanguageGroup: FormGroup;
	defaultSpokenLanguageGroup: FormGroup;
	spokenLanguageFormArray: FormArray;

	constructor(private router: Router,
		private keyValuesService: PoemsApp_Controllers_Client.KeyValues,
		private alertService: AlertService,
		private fb: FormBuilder,
		private confirmService: ConfirmService,
		private ref: ChangeDetectorRef,
	) {
		this.writtenLanguageGroup = this.newLanguageGroup();

		this.defaultSpokenLanguageGroup = this.newLanguageGroup();

		this.spokenLanguageFormArray = this.fb.array(
			[]
		);
	}

	private newLanguageGroup() {
		return this.fb.group({
			code: [''],
			display: [undefined]
		})
	}

	getLangGroup(idx: number) {
		return this.spokenLanguageFormArray.controls[idx] as FormGroup;
	}

	ngOnInit(): void {
		console.debug('current route: ' + this.router.url);
		this.keyValuesService.getValues(['settings.writtenLanguage', 'settings.defaultSpokenLanguage', 'settings.spokenLangs']).subscribe({
			next: ss => {
				const writtenLanguageText = ss['settings.writtenLanguage'];
				if (writtenLanguageText) {
					const obj = JSON.parse(writtenLanguageText);
					if (obj) {
						this.writtenLanguageGroup.patchValue(obj);
					}
				}

				const defaultSpokenLanguageText = ss['settings.defaultSpokenLanguage'];
				if (defaultSpokenLanguageText) {
					const obj = JSON.parse(defaultSpokenLanguageText);
					if (obj) {
						this.defaultSpokenLanguageGroup.patchValue(obj);
					}
				}

				const spokenLangsText = ss['settings.spokenLangs'];
				if (spokenLangsText) {
					const obj = JSON.parse(spokenLangsText) as Fonlow_PoemsApp_Data_Client.LanguageCode[];
					this.spokenLanguageFormArray = this.fb.array(
						obj.map(d => this.fb.group({
							code: d.code,
							display: d.display
						}
						))
					);
				}

				this.ref.detectChanges();
			},
			error: error => this.alertService.error(error)
		}
		);
	}

	get defaultActive(): boolean {
		return this.router.url === '/settings';
	}

	saveSetting(key: string, control: FormControl) {
		this.keyValuesService.upsertKey(key, control.value).subscribe({
			next: d => {
				control.markAsPristine();
				this.ref.detectChanges();
				this.alertService.success($localize`Saved`);
			},
			error: error => this.alertService.error(error)
		}
		)
	}

	saveSettingGroup(key: string, form: FormGroup) {
		const raw = form.getRawValue();
		this.keyValuesService.upsertKey(key, JSON.stringify(raw)).subscribe({
			next: d => {
				form.markAsPristine();
				this.ref.detectChanges();
				this.alertService.success($localize`Saved`);
			},
			error: error => this.alertService.error(error)
		}
		)
	}

	saveSettingArray(key: string, formArray: FormArray) {
		const raw = formArray.getRawValue();
		this.keyValuesService.upsertKey(key, JSON.stringify(raw)).subscribe({
			next: d => {
				formArray.markAsPristine();
				this.ref.detectChanges();
				this.alertService.success($localize`Saved`);
			},
			error: error => this.alertService.error(error)
		}
		)
	}

	addSpokenLanguage() {
		this.spokenLanguageFormArray.push(this.newLanguageGroup());
	}

	deleteSpokenLanguage(idx: number) {
		if (idx >= 0) {
			this.confirmService.open($localize`Confirm`, $localize`Are you sure to remove?`).subscribe(
				r => {
					if (r) {
						this.spokenLanguageFormArray.removeAt(idx);
					}
				}
			);

		}
	}


}
