import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Injectable, OnInit } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { AlertService, ConfirmService, TextInputService } from 'nmce';
import { Observable } from 'rxjs';
import { Fonlow_PoemsApp_Data_Client, PoemsApp_Controllers_Client } from '../../clientapi/WebApiNG2ClientAuto';
import { APP_DI_CONFIG } from '../app-config';
import { AppCache } from '../appCache';
import { PoemAssociationsChangedSubjectService } from '../_services/types';
import { TagsSelectionDialogService } from './tagsSelectionDialogService';
import { ThemePalette } from '@angular/material/core';
import { ReactiveFormsModule } from '@angular/forms';
import { NGMDModule } from '../ngmd.module';

export interface TagEx extends Fonlow_PoemsApp_Data_Client.Tag {
	count?: number | null;
}

@Component({
    selector: 'settings-tags',
    templateUrl: 'settings-tags.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: true,
	imports: [NGMDModule, ReactiveFormsModule],
	providers: [TagsSelectionDialogService]
})
export class SettingsTagsComponent implements OnInit {
	get tags(): TagEx[] {
		return AppCache.tags as TagEx[];
	}

	get tagsDic() {
		return AppCache.tagsDic;
	}

	orphansExist = false;

	readonly warnColor: ThemePalette = 'warn';
	readonly primaryColor: ThemePalette = 'primary';

	constructor(private tagsService: PoemsApp_Controllers_Client.Tags,
		private alertService: AlertService,
		private tagsSelectionDialogService: TagsSelectionDialogService,
		private poemAssociationsChangedSubjectService: PoemAssociationsChangedSubjectService,
		private confirmService: ConfirmService,
		private textInputService: TextInputService,
		private ref: ChangeDetectorRef,
	) {
	}


	ngOnInit(): void {
		this.getPoemCountOfTags();
	}

	private loadTagsWithCount() {
		this.tagsService.getAllDic(APP_DI_CONFIG.convertZhHandler).subscribe(
			{
				next: data => {
					if (data) {
						AppCache.tagsDic = data;
						AppCache.tags = [];
						for (const key in data) {
							AppCache.tags.push(data[key]); //so both the dic and the list share the same set of Tag objects
						}

						this.getPoemCountOfTags();
					}
				},
				error: error => this.alertService.error(error)
			}
		);
	}

	private getPoemCountOfTags() {
		this.tagsService.getPoemCountOfTags().subscribe({
			next: cs => {
				for (const c of cs) {
					const a = this.tagsDic[c.id] as TagEx;
					if (a) {
						a.count = c.count;
					}
				}

				this.orphansExist = cs.length != this.tags.length;
				this.ref.detectChanges();
			},
			error: error => this.alertService.error(error)
		})
	}

	showOrphanedTags() {
		this.tagsService.getOrphaned().subscribe({
			next: r => {
				if (r.length == 0) {
					this.alertService.warn($localize`No orphaned tag.`);
					return;
				}

				this.tagsSelectionDialogService.open($localize`Orphaned Tags to Delete`, r).subscribe(
					rs => {
						if (rs) {
							const ids = rs.map(d => d.id!);
							if (ids.length > 0) {
								this.tagsService.deleteOrphaned(ids).subscribe({
									next: c => {
										this.alertService.success($localize`Records deleted: ${c}`, false);
										this.loadTagsWithCount();
									},
									error: error => this.alertService.error(error)
								}
								)
							}
						}

					}
				);
			},
			error: error => this.alertService.error(error)
		}
		)
	}

	removeTag(a: TagEx) {
		this.confirmService.open($localize`Confirm`, $localize`Are you sure to delete tag ${a.name}?`, $localize`Delete`, $localize`Cancel`).subscribe(
			answer => {
				if (answer) {
					this.tagsService.delete(a.id).subscribe({
						next: r => {
							if (r) {
								const idx = this.tags.findIndex(d => d.id === a.id);
								if (idx >= 0) {
									this.tags.splice(idx, 1);
									this.ref.detectChanges();
								}

								this.getPoemCountOfTags();
								this.poemAssociationsChangedSubjectService.emit(true); //tell currentPoem in view to reload
								this.alertService.success($localize`Deleted`);
							} else {
								this.alertService.warn($localize`Record might had been deleted.`);
							}
						},
						error: error => this.alertService.error(error)
					});
				}
			}
		);
	}

	editTag(id: string) {
		const tag = this.tagsDic[id];
		if (tag) {
			var tagName = this.tagsDic[id].name;
			this.textInputService.open($localize`Edit`, $localize`New Tag Name`, tagName!, true).subscribe(
				nn => {
					const newName = nn?.trim();

					if (newName && newName != tagName) {
						if (this.tags.findIndex(d => d.name === newName) >= 0) {
							this.alertService.warn($localize`${newName} exists.`);
							return;
						}

						this.tagsService.update({ id: tag.id, name: newName }).subscribe({
							next: d => {
								tag.name = newName;
								this.ref.detectChanges();
								this.alertService.success($localize`Updated`);
							},
							error: error => this.alertService.error(error)
						})
					} else {
						this.alertService.warn($localize`Nothing to change.`);
					}
				}
			);
		} else {
			this.alertService.error('Is it possible not finding tag?');
		}

	}

}

@Injectable()
export class SettingsTagsDialogService {
	constructor(private dialog: MatDialog) { }

	open(): Observable<void> {
		const modalRef = this.dialog.open(SettingsTagsComponent, {
			disableClose: true,
			autoFocus: false,
			minWidth: '98vw',
			minHeight: '98vh',
			panelClass: 'dialog-full-content-height',
		});

		return modalRef.afterClosed();
	}

}
